window.AUTH=window.AUTH||{};window.AUTH["22-448"]={"d":"22-448","id":"2023/22-448","n":"Consumer Financial Protection Bureau v. Community Financial Services Association of America","briefs":[{"k":"petitioner","label":"Brief of petitioners Consumer Financial Protection Bureau, et al.","date":"2023-05-08","url":"https://www.supremecourt.gov/DocketPDF/22/22-448/266373/20230508190055738_22-448tsUnitedStates.pdf","side":"pet","n":121},{"k":"respondent","label":"Brief of respondents Community Financial Services Association of America, Limited, et al.","date":"2023-07-03","url":"https://www.supremecourt.gov/DocketPDF/22/22-448/270281/20230703105533891_22-448%20CFSA%20Brief%20for%20Respondents.pdf","side":"res","n":57},{"k":"reply","label":"Reply of petitioners Consumer Financial Protection Bureau, et al.","date":"2023-08-02","url":"https://www.supremecourt.gov/DocketPDF/22/22-448/274470/20230802113142512_22-448rbUnitedStates.pdf","side":"pet","n":46}],"opinion":"https://www.supremecourt.gov/opinions/23pdf/601us2r21_7648.pdf","tr":true,"items":[{"t":"case","label":"Armstrong v. Exceptional Child Ctr., Inc.","cite":"575 U.S. 320","y":2015,"id":"2014/14-15","sc":1,"sum":"A case that determines whether or not a private right of action exists under the Medicaid Act.","sumSrc":"Oyez","by":{"0":"44"}},{"t":"case","label":"Barr v. American Ass’n of Political Consultants, Inc.","cite":"140 S. Ct. 2335","y":2020,"id":"2019/19-631","sc":1,"sum":"The Court held that a provision of the Telephone Consumer Protection Act of 1991 creating an exception to the prohibition on automated calls for government debt collection calls violates the First Amendment but is severable from the remainder of the statute.","sumSrc":"Oyez","by":{"0":"39, 41"}},{"t":"case","label":"Buckley v. Valeo","cite":"424 U.S. 1","y":1976,"id":"1975/75-436","sc":1,"sum":"The Court held that both upheld and struck down portions of the Federal Election Campaign Act of 1971. Restrictions on individual donations were not a violation of the donators' First Amendment rights; but certain restrictions of campaign expenditures did violate the First Amendment.","sumSrc":"Oyez","by":{"0":"46"}},{"t":"case","label":"CFPB v. All Am. Check Cashing, Inc.","cite":"33 F.4th 218","y":2022,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.4th/33/218/","op":2,"by":{"0":"28","1":"13, 41–42","2":"20"}},{"t":"case","label":"CFPB v. Law Offices of Crystal Moroney, P.C.","cite":"63 F.4th 174","y":2023,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.4th/63/174/","op":1,"by":{"0":"14, 25, 28, 33","2":"8, 10, 12"}},{"t":"case","label":"Chiafalo v. Washington","cite":"140 S. Ct. 2316","y":2020,"id":"2019/19-465","sc":1,"op":1,"sum":"The Court held that the Constitution does not prohibit Washington's “faithless elector” law, which requires presidential electors to vote the way state law directs.","sumSrc":"Oyez","by":{"0":"18"}},{"t":"case","label":"Cincinnati Soap Co. v. United States","cite":"301 U.S. 308","y":1937,"id":"scdb/1936-117","sc":1,"op":2,"ar":1,"sum":"Section 602 of the Revenue Act of 1934 imposes a tax of 3 cents per pound upon the first domestic processing of coconut oil, and provides that all such taxes collected with respect to coconut oil wholly of Philippine production, etc., \"shall be held as a separate fund and paid to the Treasury of the Philippine Islands, but if at any time the Philippine Government provides by any law for any subsidy to be paid to the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"8, 11, 14, 19, 24","2":"8, 10"}},{"t":"case","label":"Clinton v. City of New York","cite":"524 U.S. 417","y":1998,"id":"1997/97-1374","sc":1,"op":2,"ar":2,"sum":"A case in which the Court declared that pieces of legislation passed by both houses of Congress must be either passed or vetoed as a whole, not in separate parts.","sumSrc":"Oyez","by":{"0":"19","1":"20, 27, 32","2":"6, 7, 9, 10"}},{"t":"case","label":"Collins v. Yellen","cite":"141 S. Ct. 1761","y":2021,"id":"2020/19-422","sc":1,"ar":1,"sum":"Because the Federal Housing Finance Agency (FHFA) did not exceed its authority under the Housing and Economic Recovery Act of 2008 as a conservator of Fannie Mae and Freddie Mac, the anti-injunction provisions of the Recovery Act bar the statutory claim brought by shareholders of those entities; the Recovery Act’s structure, which restricts the President’s power to remove the FHFA Director, violates the separation of powers.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"9, 35, 39, 43","1":"7–8, 39, 46–47, 51","2":"14, 15"}},{"t":"case","label":"Community Fin. Servs. Ass’n of Am., Ltd. v. CFPB","cite":"143 S. Ct. 981","y":2023,"url":"https://www.courtlistener.com/c/S.%20Ct./143/981/","sc":1,"by":{"0":"7"}},{"t":"case","label":"Free Enter. Fund v. Public Co. Accounting Oversight Bd.","cite":"561 U.S. 477","y":2010,"id":"2009/08-861","sc":1,"op":1,"sum":"The Court held that the Sarbanes-Oxley Act violated the Appointment Clause of the Constitution.","sumSrc":"Oyez","by":{"0":"33, 39, 45","1":"17, 24, 27, 44","2":"16, 17"}},{"t":"case","label":"Harlow v. Fitzgerald","cite":"457 U.S. 800","y":1982,"id":"1981/80-945","sc":1,"sum":"The Court held that government officials are entitled to qualified immunity but not absolute immunity. Absolute immunity is only available for specific functions that require a total shield from liability.","sumSrc":"Oyez","by":{"0":"46"}},{"t":"case","label":"Harrington v. Bush","cite":"553 F.2d 190","y":1977,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/553/190/","by":{"0":"24"}},{"t":"case","label":"Hudson v. Michigan","cite":"547 U.S. 586","y":2006,"id":"2005/04-1360","sc":1,"sum":"The Court ruled that the general rule excluding evidence obtained in violation of the Fourth Amendment does not apply to the \"knock-and-announce\" rule.","sumSrc":"Oyez","by":{"0":"46"}},{"t":"case","label":"Knote v. United States","cite":"95 U.S. 149","y":1877,"id":"scdb/1877-053","sc":1,"op":1,"sum":"The petition of the claimant alleged that he was the owner of certain described personal property in West Virginia, ivhich was seized and libelled by the authorities of the United States on the alleged ground of his treason and rebellion; that, by a decree of the District Court for that district, the property was condemned and forfeited to the United States, and sold; and the net proceeds of the sale, amounting to …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"15"}},{"t":"case","label":"Lebron v. National R.R. Passenger Corp.","cite":"513 U.S. 374","y":1995,"id":"1994/93-1525","sc":1,"sum":"Where, as here, the Government creates a corporation by special law, for the furtherance of governmental objectives, and retains for itself permanent authority to appoint a majority of that corporation's directors, the corporation is part of the Government for purposes of the First Amendment.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"37","1":"30"}},{"t":"case","label":"Lincoln v. Vigil","cite":"508 U.S. 182","y":1993,"id":"1992/91-1833","sc":1,"sum":"The Indian Health Service receives yearly lump-sum appropriations from Congress, and expends the funds under authority of the Snyder Act and the Indian Health Care Improvement Act to provide health care for American Indian and Alaska Native people. Out of these appropriations the Service funded, from 1978 to 1985, the Indian Children's Program (Program), which provided clinical services to handicapped Indian …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"19, 26"}},{"t":"case","label":"Maine Cmty. Health Options v. United States","cite":"140 S. Ct. 1308","y":2020,"id":"2019/18-1023","sc":1,"sum":"The Court held that the federal government has an obligation to pay the insurance carriers in this case for losses incurred under the \"Risk Corridors\" program of the Affordable Care Act as a result of their participation in the health care marketplace.","sumSrc":"Oyez","by":{"0":"16"}},{"t":"case","label":"NLRB v. Noel Canning","cite":"573 U.S. 513","y":2014,"id":"2013/12-1281","sc":1,"op":1,"sum":"A case in which the Court further defined the limitations on the presidential powers granted by the Recess Appointments Clause.","sumSrc":"Oyez","by":{"0":"18","1":"36","2":"18"}},{"t":"case","label":"Norton v. Shelby Cnty.","cite":"118 U.S. 425","y":1886,"id":"scdb/1885-275","sc":1,"sum":"This court follows the decisions of the highest court of a State, in construing the Constitution and laws of the State, unless they conflict with or impair the efficacy of some principle of the Federal Constitution, or of a Federal statute, or a rule of commercial or general law.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"46"}},{"t":"case","label":"OPM v. Richmond","cite":"496 U.S. 414","y":1990,"id":"1989/88-1943","sc":1,"op":2,"ar":1,"sum":"The Court held that the Appropriations Clause of the Constitution explicitly states that no money can be paid from the Treasury unless specifically authorized by a statute. Since there is a statute that denies Richmond his benefits, and there is not one that provides an exception, the Court held that Richmond’s receipt of incorrect information cannot affect the non-payment of his benefits.","sumSrc":"Oyez","by":{"0":"7, 14, 38","1":"11, 13, 15, 18, 26–27, 33, 41–42, 45","2":"14, 16"}},{"t":"case","label":"PHH Corp. v. CFPB","cite":"881 F.3d 75","y":2018,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/881/75/","by":{"0":"25","1":"5, 38, 40"}},{"t":"case","label":"Seila Law LLC v. CFPB","cite":"140 S. Ct. 2183","y":2020,"id":"2019/19-7","sc":1,"op":10,"ar":4,"sum":"The Court held that the vesting of substantial executive authority in the Consumer Financial Protection Bureau, an independent agency led by a single director, violates the separation of powers, but the statutory provision creating that violation, 12 U.S.C. § 5491(c)(3) is severable from the Dodd-Frank Act.","sumSrc":"Oyez","by":{"0":"6, 12, 14, 36, 39, 40, 41","1":"1–4, 22–23, 34, 38–39, 43–45","2":"3"}},{"t":"case","label":"Seminole Tribe of Fla. v. Florida","cite":"517 U.S. 44","y":1996,"id":"1995/94-12","sc":1,"sum":"In a 5-to-4 decision, The Court held that Congress did intend to abrogate states' sovereign immunity under the IGRA but that the Indian Commerce Clause (and by implication the Commerce Clause) did not give Congress that power. Under the Eleventh Amendment, all states are regarded as sovereign entities.","sumSrc":"Oyez","by":{"0":"44"}},{"t":"case","label":"United Biscuit Co. of Am. v. Wirtz","cite":"359 F.2d 206","y":1965,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/359/206/","by":{"0":"25"}},{"t":"case","label":"United States v. Arthrex","cite":"141 S. Ct. 1970","y":2021,"id":"2020/19-1434","sc":1,"sum":"The unreviewable authority wielded by Administrative Patent Judges during inter partes review is incompatible with their appointment by the Secretary of Commerce to an inferior office; the judgment of the Federal Circuit is vacated, and the case is remanded.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"40","1":"18, 33, 43–45"}},{"t":"case","label":"United States v. Morrison","cite":"449 U.S. 361","y":1981,"id":"1980/79-395","sc":1,"sum":"For sake of argument, the Court granted that Morrison's Sixth Amendment right to counsel had been violated, but held that this did not merit the dismissal of all charges since the conduct of the agents did not prejudice the outcome of the trial. The Court maintained that Sixth Amendment violations should not be remedied beyond the scope of the harm they inflicted upon the defendant.","sumSrc":"Oyez","by":{"0":"45","2":"24"}},{"t":"case","label":"United States v. Vaello Madero","cite":"142 S. Ct. 1539","y":2022,"id":"2021/20-303","sc":1,"sum":"The Constitution does not require Congress to make Supplemental Security Income benefits available to residents of Puerto Rico.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"14"}},{"t":"case","label":"United States Dep’t of the Navy v. Federal Labor Relations Auth.","cite":"665 F.3d 1339","y":2012,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/665/1339/","by":{"0":"14, 24, 38","1":"1, 12, 15"}},{"t":"case","label":"Waite v. Santa Cruz","cite":"184 U.S. 302","y":1902,"id":"scdb/1901-108","sc":1,"sum":"On the facts, as stated in the opinion of the court, the city of Santa Cruz is estopped to dispute the truth of the recitals in the bonds in suit in this case, which stated that they were issued in pursuance of the act of California of 1893, as well as in conformity With the constitution of California, authorizing it to incur indebtedness or liability with the assent of, two thirds of the qualified voters at an …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"46"}},{"t":"case","label":"Winter v. Natural Res. Def. Council, Inc.","cite":"555 U.S. 7","y":2008,"id":"2008/07-1239","sc":1,"sum":"The Court held that the standard for properly granting a preliminary injunction is not based on the \"possibility\" of irreparable harm to marine life, but rather that \"irreparable injury is likely\" in the absence of such an injunction.","sumSrc":"Oyez","by":{"0":"45"}},{"t":"law","label":"Pub. L. No. 91-206","url":"https://www.govinfo.gov/link/statute/84/49","by":{"0":"23"}},{"t":"usc","label":"5 U.S.C. § 701","url":"https://www.law.cornell.edu/uscode/text/5/701","by":{"0":"44"}},{"t":"usc","label":"5 U.S.C. § 702","url":"https://www.law.cornell.edu/uscode/text/5/702","by":{"0":"44"}},{"t":"usc","label":"31 U.S.C. § 1341","url":"https://www.law.cornell.edu/uscode/text/31/1341","by":{"0":"43"}},{"t":"usc","label":"31 U.S.C. § 1349","url":"https://www.law.cornell.edu/uscode/text/31/1349","subs":["(a)"],"by":{"0":"44"}},{"t":"usc","label":"31 U.S.C. § 1350","url":"https://www.law.cornell.edu/uscode/text/31/1350","by":{"0":"44"}},{"t":"usc","label":"12 U.S.C. § 1811","url":"https://www.law.cornell.edu/uscode/text/12/1811","by":{"0":"23"}},{"t":"usc","label":"12 U.S.C. § 1815","url":"https://www.law.cornell.edu/uscode/text/12/1815","subs":["(d)"],"stext":{"head":"§1815. Deposit insurance","paras":[[0,"(a) Application to Corporation required"],[0,"(1) In general"],[1,"Except as provided in paragraphs (2) and (3), any depository institution which is engaged in the business of receiving deposits other than trust funds (as defined in section 1813(p) of this title), upon application to and examination by the Corporation and approval by the Board of Directors, may become an insured depository institution."],[0,"(2) Interim depository institutions"],[1,"In the case of any interim Federal depository institution that is chartered by the appropriate Federal banking agency and will not open for business, the depository institution shall be an insured depository institution upon the issuance of the institution's charter by the agency."],[0,"(3) Application and approval not required in cases of continued insurance"],[1,"Paragraph (1) shall not apply in the case of any depository institution whose insured status is continued pursuant to section 1814 of this title."],[0,"(4) Review requirements"],[1,"In reviewing any application under this subsection, the Board of Directors shall consider the factors described in section 1816 of this title in determining whether to approve the application for insurance."],[0,"(5) Notice of denial of application for insurance"],[1,"If the Board of Directors votes to deny any application for insurance by any depository institution, the Board of Directors shall promptly notify the appropriate Federal banking agency and, in the case of any State depository institution, the appropriate State banking supervisor of the denial of such application, giving specific reasons in writing for the Board of Directors' determination with reference to the factors described in section 1816 of this title."],[0,"(6) Nondelegation requirement"],[1,"The authority of the Board of Directors to make any determination to deny any application under this subsection may not be delegated by the Board of Directors."],[0,"(b) Foreign branch nonmember banks; matters considered"],[0,"Subject to the provisions of this chapter and to such terms and conditions as the Board of Directors may impose, any branch of a foreign bank, upon application by the bank to the Corporation, and examination by the Corporation of the branch, and approval by the Board of Directors, may become an insured branch. Before approving any such application, the Board of Directors shall give consideration to—"],[1,"(1) the financial history and condition of the bank,"],[1,"(2) the adequacy of its capital structure,"],[1,"(3) its future earnings prospects,"],[1,"(4) the general character and fitness of its management, including but not limited to the management of the branch proposed to be insured,"],[1,"(5) the risk presented to the Deposit Insurance Fund,"],[1,"(6) the convenience and needs of the community to be served by the branch,"],[1,"(7) whether or not its corporate powers, insofar as they will be exercised through the proposed insured branch, are consistent with the purposes of this chapter, and"],[1,"(8) the probable adequacy and reliability of information supplied and to be supplied by the bank to the Corporation to enable it to carry out its functions under this chapter."],[0,"(c) Protection to Deposit Insurance Fund; surety bond, pledge of assets, etc.; injunction"],[0,"(1) Before any branch of a foreign bank becomes an insured branch, the bank shall deliver to the Corporation or as the Corporation may direct a surety bond, a pledge of assets, or both, in such amounts and of such types as the Corporation may require or approve, for the purpose set forth in paragraph (4) of this subsection."],[0,"(2) After any branch of a foreign bank becomes an insured branch, the bank shall maintain on deposit with the Corporation, or as the Corporation may direct, surety bonds or assets or both, in such amounts and of such types as shall be determined from time to time in accordance with such regulations as the Board of Directors may prescribe. Such regulations may impose differing requirements on the basis of any factors which in the judgment of the Board of Directors are reasonably related to the purpose set forth in paragraph (4)."],[0,"(3) The Corporation may require of any given bank larger deposits of bonds and assets than required under paragraph (2) of this subsection if, in the judgment of the Corporation, the situation of that bank or any branch thereof is or becomes such that the deposits of bonds and assets otherwise required under this section would not adequately fulfill the purpose set forth in paragraph (4). The imposition of any such additional requirements may be without notice or opportunity for hearing, but the Corporation shall afford an opportunity to any such bank to apply for a reduction or removal of any such additional requirements so imposed."],[0,"(4) The purpose of the surety bonds and pledges of assets required under this subsection is to provide protection to the Deposit Insurance Fund against the risks entailed in insuring the domestic deposits of a foreign bank whose activities, assets, and personnel are in large part outside the jurisdiction of the United States. In the implementation of its authority under this subsection, however, the Corporation shall endeavor to avoid imposing requirements on such banks which would unnecessarily place them at a competitive disadvantage in relation to domestically incorporated banks."],[0,"(5) In the case of any failure or threatened failure of a foreign bank to comply with any requirement imposed under this subsection (c), the Corporation, in addition to all other administrative and judicial remedies, may apply to any United States district court, or United States court of any territory, within the jurisdiction of which any branch of the bank is located, for an injunction to compel such bank and any officer, employee, or agent thereof, or any other person having custody or control of any of its assets, to deliver to the Corporation such assets as may be necessary to meet such requirement, and to take any other action necessary to vest the Corporation with control of assets so delivered. If the court shall determine that there has been any such failure or threatened failure to comply with any such requirement, it shall be the duty of the court to issue such injunction. The propriety of the requirement may be litigated only as provided in chapter 7 of title 5, and may not be made an issue in an action for an injunction under this paragraph."],[0,"(d) Insurance fees"],[0,"(1) In general"],[2,"Any institution that becomes insured by the Corporation, and any noninsured branch that becomes insured by the Corporation, shall pay the Corporation any fee which the Corporation may by regulation prescribe, after giving due consideration to the need to establish and maintain the reserve ratio of the Deposit Insurance Fund."],[0,"(2) Fee credited to the Deposit Insurance Fund"],[1,"The fee paid by the depository institution under paragraph (1) shall be credited to the Deposit Insurance Fund."],[0,"(3) Exception for certain depository institutions"],[2,"Any depository institution that becomes an insured depository institution by operation of section 1814(a) of this title shall not pay any fee."],[0,"(e) Liability of commonly controlled depository institutions"],[0,"(1) In general"],[0,"(A) Liability established"],[2,"Any insured depository institution shall be liable for any loss incurred by the Corporation, or any loss which the Corporation reasonably anticipates incurring, after August 9, 1989, in connection with—"],[3,"(i) the default of a commonly controlled insured depository institution; or"],[3,"(ii) any assistance provided by the Corporation to any commonly controlled insured depository institution in danger of default."],[0,"(B) Payment upon notice"],[2,"An insured depository institution shall pay the amount of any liability to the Corporation under subparagraph (A) upon receipt of written notice by the Corporation in accordance with this subsection."],[0,"(C) Notice required to be provided within 2 years of loss"],[2,"No insured depository institution shall be liable to the Corporation under subparagraph (A) if written notice with respect to such liability is not received by such institution before the end of the 2-year period beginning on the date the Corporation incurred the loss."],[0,"(2) Amount of compensation; procedures"],[0,"(A) Use of estimates"],[2,"When an insured depository institution is in default or requires assistance to prevent default, the Corporation shall—"],[3,"(i) in good faith, estimate the amount of the loss the Corporation will incur from such default or assistance;"],[3,"(ii) if, with respect to such insured depository institution, there is more than 1 commonly controlled insured depository institution, estimate the amount of each such commonly controlled depository institution's share of such liability; and"],[3,"(iii) advise each commonly controlled depository institution of the Corporation's estimate of the amount of such institution's liability for such losses."],[0,"(B) Procedures; immediate payment"],[2,"The Corporation, after consultation with the appropriate Federal banking agency and the appropriate State chartering agency, shall—"],[3,"(i) on a case-by-case basis, establish the procedures and schedule under which any insured depository institution shall reimburse the Corporation for such institution's liability under paragraph (1) in connection with any commonly controlled insured depository institution; or"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/12/1815?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1815. Deposit insurance","tname":"Banks and Banking","by":{"0":"23"}},{"t":"usc","label":"12 U.S.C. § 1818","url":"https://www.law.cornell.edu/uscode/text/12/1818","subs":["(a)(1)"],"ar":1,"by":{"0":"36, 34"}},{"t":"usc","label":"12 U.S.C. § 1820","url":"https://www.law.cornell.edu/uscode/text/12/1820","subs":["(e)"],"by":{"0":"23"}},{"t":"usc","label":"12 U.S.C. § 1828","url":"https://www.law.cornell.edu/uscode/text/12/1828","by":{"0":"36"}},{"t":"law","label":"Pub. L. No. 117-103","url":"https://www.govinfo.gov/link/plaw/117/public/103","by":{"0":"26","1":"35","2":"7"}},{"t":"usc","label":"12 U.S.C. § 5301","url":"https://www.law.cornell.edu/uscode/text/12/5301","by":{"0":"2"}},{"t":"usc","label":"12 U.S.C. § 5302","url":"https://www.law.cornell.edu/uscode/text/12/5302","by":{"0":"12, 40, 41","2":"20"}},{"t":"usc","label":"12 U.S.C. § 5491","url":"https://www.law.cornell.edu/uscode/text/12/5491","subs":["(a)"],"stext":{"head":"§5491. Establishment of the Bureau of Consumer Financial Protection","paras":[[0,"(a) Bureau established"],[0,"There is established in the Federal Reserve System, an independent bureau to be known as the \"Bureau of Consumer Financial Protection\", which shall regulate the offering and provision of consumer financial products or services under the Federal consumer financial laws. The Bureau shall be considered an Executive agency, as defined in section 105 of title 5. Except as otherwise provided expressly by law, all Federal laws dealing with public or Federal contracts, property, works, officers, employees, budgets, or funds, including the provisions of chapters 5 and 7 of title 5, shall apply to the exercise of the powers of the Bureau."],[0,"(b) Director and Deputy Director"],[0,"(1) In general"],[1,"There is established the position of the Director, who shall serve as the head of the Bureau."],[0,"(2) Appointment"],[1,"Subject to paragraph (3), the Director shall be appointed by the President, by and with the advice and consent of the Senate."],[0,"(3) Qualification"],[1,"The President shall nominate the Director from among individuals who are citizens of the United States."],[0,"(4) Compensation"],[1,"The Director shall be compensated at the rate prescribed for level II of the Executive Schedule under section 5313 of title 5."],[0,"(5) Deputy Director"],[1,"There is established the position of Deputy Director, who shall—"],[2,"(A) be appointed by the Director; and"],[2,"(B) serve as acting Director in the absence or unavailability of the Director."],[0,"(c) Term"],[0,"(1) In general"],[1,"The Director shall serve for a term of 5 years."],[0,"(2) Expiration of term"],[1,"An individual may serve as Director after the expiration of the term for which appointed, until a successor has been appointed and qualified."],[0,"(3) Removal for cause"],[1,"The President may remove the Director for inefficiency, neglect of duty, or malfeasance in office."],[0,"(d) Service restriction"],[0,"No Director or Deputy Director may hold any office, position, or employment in any Federal reserve bank, Federal home loan bank, covered person, or service provider during the period of service of such person as Director or Deputy Director."],[0,"(e) Offices"],[0,"The principal office of the Bureau shall be in the District of Columbia. The Director may establish regional offices of the Bureau, including in cities in which the Federal reserve banks, or branches of such banks, are located, in order to carry out the responsibilities assigned to the Bureau under the Federal consumer financial laws."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/12/5491?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§5491. Establishment of the Bureau of Consumer Financial Protection","tname":"Banks and Banking","by":{"0":"2, 33","1":"4","2":"15"}},{"t":"usc","label":"12 U.S.C. § 5496","url":"https://www.law.cornell.edu/uscode/text/12/5496","subs":["(a)","(b)","(c)(2)"],"by":{"0":"4, 37, 37, 4, 37"}},{"t":"usc","label":"12 U.S.C. § 5497","url":"https://www.law.cornell.edu/uscode/text/12/5497","subs":["(a)","(a)(1)","(a)(2)","(a)(2)(A)","(a)(2)(A)(iii)","(a)(2)(B)","(a)(2)(C)","(a)(5)","(b)(1)","(b)(2)","(c)(1)","(c)(2)","(d)","(b)(3)"],"stext":{"head":"§5497. Funding; penalties and fines","paras":[[0,"(a) Transfer of funds from Board Of Governors"],[0,"(1) In general"],[1,"Each year (or quarter of such year), beginning on the designated transfer date, and each quarter thereafter, the Board of Governors shall transfer to the Bureau from the combined earnings of the Federal Reserve System, the amount determined by the Director to be reasonably necessary to carry out the authorities of the Bureau under Federal consumer financial law, taking into account such other sums made available to the Bureau from the preceding year (or quarter of such year)."],[0,"(2) Funding cap"],[0,"(A) In general"],[2,"Notwithstanding paragraph (1), and in accordance with this paragraph, the amount that shall be transferred to the Bureau in each fiscal year shall not exceed a fixed percentage of the total operating expenses of the Federal Reserve System, as reported in the Annual Report, 2009, of the Board of Governors, equal to—"],[3,"(i) 10 percent of such expenses in fiscal year 2011;"],[3,"(ii) 11 percent of such expenses in fiscal year 2012; and"],[3,"(iii) 12 percent of such expenses in fiscal year 2013, and in each year thereafter."],[0,"(B) Adjustment of amount"],[2,"The dollar amount referred to in subparagraph (A)(iii) shall be adjusted annually, using the percent increase, if any, in the employment cost index for total compensation for State and local government workers published by the Federal Government, or the successor index thereto, for the 12-month period ending on September 30 of the year preceding the transfer."],[0,"(C) Reviewability"],[2,"Notwithstanding any other provision in this title,1 the funds derived from the Federal Reserve System pursuant to this subsection shall not be subject to review by the Committees on Appropriations of the House of Representatives and the Senate."],[0,"(3) Transition period"],[1,"Beginning on July 21, 2010, and until the designated transfer date, the Board of Governors shall transfer to the Bureau the amount estimated by the Secretary needed to carry out the authorities granted to the Bureau under Federal consumer financial law, from July 21, 2010 until the designated transfer date."],[0,"(4) Budget and financial management"],[0,"(A) Financial operating plans and forecasts"],[2,"The Director shall provide to the Director of the Office of Management and Budget copies of the financial operating plans and forecasts of the Director, as prepared by the Director in the ordinary course of the operations of the Bureau, and copies of the quarterly reports of the financial condition and results of operations of the Bureau, as prepared by the Director in the ordinary course of the operations of the Bureau."],[0,"(B) Financial statements"],[2,"The Bureau shall prepare annually a statement of—"],[3,"(i) assets and liabilities and surplus or deficit;"],[3,"(ii) income and expenses; and"],[3,"(iii) sources and application of funds."],[0,"(C) Financial management systems"],[2,"The Bureau shall implement and maintain financial management systems that comply substantially with Federal financial management systems requirements and applicable Federal accounting standards."],[0,"(D) Assertion of internal controls"],[2,"The Director shall provide to the Comptroller General of the United States an assertion as to the effectiveness of the internal controls that apply to financial reporting by the Bureau, using the standards established in section 3512(c) of title 31."],[0,"(E) Rule of construction"],[2,"This subsection may not be construed as implying any obligation on the part of the Director to consult with or obtain the consent or approval of the Director of the Office of Management and Budget with respect to any report, plan, forecast, or other information referred to in subparagraph (A) or any jurisdiction or oversight over the affairs or operations of the Bureau."],[0,"(F) Financial statements"],[2,"The financial statements of the Bureau shall not be consolidated with the financial statements of either the Board of Governors or the Federal Reserve System."],[0,"(5) Audit of the Bureau"],[0,"(A) In general"],[2,"The Comptroller General shall annually audit the financial transactions of the Bureau in accordance with the United States generally accepted government auditing standards, as may be prescribed by the Comptroller General of the United States. The audit shall be conducted at the place or places where accounts of the Bureau are normally kept. The representatives of the Government Accountability Office shall have access to the personnel and to all books, accounts, documents, papers, records (including electronic records), reports, files, and all other papers, automated data, things, or property belonging to or under the control of or used or employed by the Bureau pertaining to its financial transactions and necessary to facilitate the audit, and such representatives shall be afforded full facilities for verifying transactions with the balances or securities held by depositories, fiscal agents, and custodians. All such books, accounts, documents, records, reports, files, papers, and property of the Bureau shall remain in possession and custody of the Bureau. The Comptroller General may obtain and duplicate any such books, accounts, documents, records, working papers, automated data and files, or other information relevant to such audit without cost to the Comptroller General, and the right of access of the Comptroller General to such information shall be enforceable pursuant to section 716(c) of title 31."],[0,"(B) Report"],[2,"The Comptroller General shall submit to the Congress a report of each annual audit conducted under this subsection. The report to the Congress shall set forth the scope of the audit and shall include the statement of assets and liabilities and surplus or deficit, the statement of income and expenses, the statement of sources and application of funds, and such comments and information as may be deemed necessary to inform Congress of the financial operations and condition of the Bureau, together with such recommendations with respect thereto as the Comptroller General may deem advisable. A copy of each report shall be furnished to the President and to the Bureau at the time submitted to the Congress."],[0,"(C) Assistance and costs"],[2,"For the purpose of conducting an audit under this subsection, the Comptroller General may, in the discretion of the Comptroller General, employ by contract, without regard to section 6101 of title 41, professional services of firms and organizations of certified public accountants for temporary periods or for special purposes. Upon the request of the Comptroller General, the Director of the Bureau shall transfer to the Government Accountability Office from funds available, the amount requested by the Comptroller General to cover the full costs of any audit and report conducted by the Comptroller General. The Comptroller General shall credit funds transferred to the account established for salaries and expenses of the Government Accountability Office, and such amount shall be available upon receipt and without fiscal year limitation to cover the full costs of the audit and report."],[0,"(b) Consumer Financial Protection Fund"],[0,"(1) Separate fund in Federal Reserve established"],[1,"There is established in the Federal Reserve a separate fund, to be known as the \"Bureau of Consumer Financial Protection Fund\" (referred to in this section as the \"Bureau Fund\"). The Bureau Fund shall be maintained and established at a Federal reserve bank, in accordance with such requirements as the Board of Governors may impose."],[0,"(2) Fund receipts"],[1,"All amounts transferred to the Bureau under subsection (a) shall be deposited into the Bureau Fund."],[0,"(3) Investment authority"],[0,"(A) Amounts in Bureau Fund may be invested"],[2,"The Bureau may request the Board of Governors to direct the investment of the portion of the Bureau Fund that is not, in the judgment of the Bureau, required to meet the current needs of the Bureau."],[0,"(B) Eligible investments"],[2,"Investments authorized by this paragraph shall be made in obligations of the United States or obligations that are guaranteed as to principal and interest by the United States, with maturities suitable to the needs of the Bureau Fund, as determined by the Bureau."],[0,"(C) Interest and proceeds credited"],[2,"The interest on, and the proceeds from the sale or redemption of, any obligations held in the Bureau Fund shall be credited to the Bureau Fund."],[0,"(c) Use of funds"],[0,"(1) In general"],[1,"Funds obtained by, transferred to, or credited to the Bureau Fund shall be immediately available to the Bureau and under the control of the Director, and shall remain available until expended, to pay the expenses of the Bureau in carrying out its duties and responsibilities. The compensation of the Director and other employees of the Bureau and all other expenses thereof may be paid from, obtained by, transferred to, or credited to the Bureau Fund under this section."],[0,"(2) Funds that are not Government funds"],[1,"Funds obtained by or transferred to the Bureau Fund shall not be construed to be Government funds or appropriated monies."],[0,"(3) Amounts not subject to apportionment"],[1,"Notwithstanding any other provision of law, amounts in the Bureau Fund and in the Civil Penalty Fund established under subsection (d) shall not be subject to apportionment for purposes of chapter 15 of title 31 or under any other authority."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/12/5497?type=usc&year=mostrecent&link-type=html"},"op":8,"head":"§5497. Funding; penalties and fines","tname":"Banks and Banking","by":{"0":"3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3","1":"1–2, 5–6, 16, 18–19, 22, 25, 29, 32, 44–45","2":"9, 10, 19, 20, 8-10, 15, 20, 6, 6, 8, 8, 10, 20"}},{"t":"usc","label":"12 U.S.C. § 5511","url":"https://www.law.cornell.edu/uscode/text/12/5511","subs":["(a)","(b)","(c)"],"by":{"0":"3","2":"10, 10"}},{"t":"usc","label":"12 U.S.C. § 5512","url":"https://www.law.cornell.edu/uscode/text/12/5512","subs":["(b)(1)"],"by":{"0":"3"}},{"t":"usc","label":"12 U.S.C. § 5531","url":"https://www.law.cornell.edu/uscode/text/12/5531","subs":["(b)"],"by":{"0":"3, 5"}},{"t":"usc","label":"12 U.S.C. § 5581","url":"https://www.law.cornell.edu/uscode/text/12/5581","subs":["(b)(1)","(b)(2)","(b)(4)","(b)(6)"],"by":{"0":"2, 36, 36, 36, 36"}},{"t":"usc","label":"15 U.S.C. § 1693","url":"https://www.law.cornell.edu/uscode/text/15/1693","by":{"0":"47"}},{"t":"usc","label":"15 U.S.C. § 1681","url":"https://www.law.cornell.edu/uscode/text/15/1681","by":{"0":"47"}},{"t":"usc","label":"15 U.S.C. § 1692","url":"https://www.law.cornell.edu/uscode/text/15/1692","by":{"0":"47"}},{"t":"usc","label":"12 U.S.C. § 1131","url":"https://www.law.cornell.edu/uscode/text/12/1131","by":{"0":"23"}},{"t":"usc","label":"12 U.S.C. § 2250","url":"https://www.law.cornell.edu/uscode/text/12/2250","subs":["(b)(2)"],"stext":{"head":"§2250. Farm Credit Administration operating expenses fund","paras":[[0,"(a) Determinations required"],[0,"(1) Generally"],[1,"Prior to the first day of each fiscal year, the Farm Credit Administration shall determine—"],[2,"(A) the cost of administering this chapter for the subsequent fiscal year, including expenses for official functions;"],[2,"(B) the amount of assessments that will be required to pay such administrative expenses, taking into consideration the funds contained in the Administrative Expense Account, and maintain a necessary reserve; and"],[2,"(C) the amount of assessments that will be required to pay the costs of supervising and examining the Mortgage Corporation established under subchapter VIII."],[0,"(2) Apportionments"],[1,"On the basis of the determinations made under paragraph (1), the Farm Credit Administration shall—"],[2,"(A) apportion the amount of the assessment described in paragraph (1)(B) among the System institutions on a basis that is determined to be equitable by the Farm Credit Administration;"],[2,"(B) assess and collect such apportioned amounts from time to time during the fiscal year as determined necessary by the Farm Credit Administration; and"],[2,"(C) assess and collect from the Mortgage Corporation, from time to time during the fiscal year, the amount described in paragraph (1)(C)."],[0,"(b) Deposits into fund"],[0,"(1) Treasury fund"],[1,"The amounts collected under subsection (a) shall be deposited in the Farm Credit Administration Administrative Expense Account. The Expense Account shall be maintained in the Treasury of the United States and shall be available, without regard, for purposes of sequestration, to the Balanced Budget and Emergency Deficit Control Act of 1985 [2 U.S.C. 900 et seq.], to pay the expenses of the Farm Credit Administration."],[0,"(2) Nongovernment funds"],[1,"The funds contained in the Expense Account shall not be construed to be Federal Government funds or appropriated moneys."],[0,"(3) Investment"],[0,"(A) Authority"],[2,"On request of the Farm Credit Administration, the Secretary of the Treasury shall invest and reinvest such amounts contained in the Expense Account as, in the determination of the Farm Credit Administration, are in excess of the amounts necessary for current expenses of the Farm Credit Administration."],[0,"(B) Returns"],[2,"All income earned from such investments and reinvestments shall be deposited in the Expense Account."],[0,"(C) Type"],[2,"Such investments shall be made in public debt securities with maturities suitable to the needs of the Expense Account, as determined by the Farm Credit Administration, and bearing interest at rates determined by the Secretary of the Treasury, taking into consideration current market yields on outstanding marketable obligations of the United States of comparable maturities."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/12/2250?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§2250. Farm Credit Administration operating expenses fund","tname":"Banks and Banking","by":{"0":"23, 32, 37"}},{"t":"usc","label":"12 U.S.C. § 1751","url":"https://www.law.cornell.edu/uscode/text/12/1751","by":{"0":"23"}},{"t":"usc","label":"12 U.S.C. § 1755","url":"https://www.law.cornell.edu/uscode/text/12/1755","subs":["(a)","(b)"],"stext":{"head":"§1755. Fees","paras":[[0,"(a) Payment by Federal credit union to Administration"],[0,"In accordance with rules prescribed by the Board, each Federal credit union shall pay to the Administration an annual operating fee which may be composed of one or more charges identified as to the function or functions for which assessed."],[0,"(b) Determinations of amount, assessment periods, and payment dates"],[0,"The fee assessed under this section shall be determined according to a schedule, or schedules, or other method determined by the Board to be appropriate, which gives due consideration to the expenses of the Administration in carrying out its responsibilities under this chapter and to the ability of Federal credit unions to pay the fee. The Board shall, among other things, determine the periods for which the fee shall be assessed and the date or dates for the payment of the fee or increments thereof."],[0,"(c) Supervision charge exception; waiver of payment"],[0,"If the annual operating fee is composed of separate charges, no supervision charge shall be payable by a Federal credit union, and the Board may waive payment of any or all other charges comprising the fee, with respect to the year in which its charter is issued, or in which final distribution is made in its liquidation or the charter is canceled."],[0,"(d) Payment into Treasury of United States"],[0,"All operating fees shall be deposited with the Treasurer of the United States for the account of the Administration and may be expended by the Board to defray the expenses incurred in carrying out the provisions of this chapter including the examination and supervision of Federal credit unions."],[0,"(e) Investment of annual operating fees not needed for current operations"],[0,"(1) Upon request of the Board, the Secretary of the Treasury shall invest and reinvest such portions of the annual operating fees deposited under subsection (d) as the Board determines are not needed for current operations."],[0,"(2) Such investments may be made only in interest bearing securities of the United States with maturities requested by the Board bearing interest at rates determined by the Secretary of the Treasury, taking into consideration current market yields on outstanding marketable obligations of the United States of comparable maturities."],[0,"(3) All income derived from such investments and reinvestments shall be deposited to the account of the Administration described in subsection (d)."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/12/1755?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1755. Fees","tname":"Banks and Banking","by":{"0":"23, 23"}},{"t":"usc","label":"12 U.S.C. § 221","url":"https://www.law.cornell.edu/uscode/text/12/221","by":{"0":"23"}},{"t":"usc","label":"12 U.S.C. § 222","url":"https://www.law.cornell.edu/uscode/text/12/222","by":{"0":"34","1":"37"}},{"t":"usc","label":"12 U.S.C. § 243","url":"https://www.law.cornell.edu/uscode/text/12/243","stext":{"head":"§243. Assessments upon Federal reserve banks to pay expenses","paras":[[0,"The Board of Governors of the Federal Reserve System shall have power to levy semiannually upon the Federal reserve banks, in proportion to their capital stock and surplus, an assessment sufficient to pay its estimated expenses and the salaries of its members and employees for the half year succeeding the levying of such assessment, together with any deficit carried forward from the preceding half year, and such assessments may include amounts sufficient to provide for the acquisition by the Board in its own name of such site or building in the District of Columbia as in its judgment alone shall be necessary for the purpose of providing suitable and adequate quarters for the performance of its functions. After September 1, 2000, the Board may also use such assessments to acquire, in its own name, a site or building (in addition to the facilities existing on such date) to provide for the performance of the functions of the Board. After approving such plans, estimates, and specifications as it shall have caused to be prepared, the Board may, notwithstanding any other provision of law, cause to be constructed on any site so acquired by it a building or buildings suitable and adequate in its judgment for its purposes and proceed to take all such steps as it may deem necessary or appropriate in connection with the construction, equipment, and furnishing of such building or buildings. The Board may maintain, enlarge, or remodel any building or buildings so acquired or constructed and shall have sole control of such building or buildings and space therein."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/12/243?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§243. Assessments upon Federal reserve banks to pay expenses","tname":"Banks and Banking","by":{"0":"22, 23, 26, 30, 33","1":"37","2":"3, 18"}},{"t":"usc","label":"12 U.S.C. § 244","url":"https://www.law.cornell.edu/uscode/text/12/244","by":{"0":"22, 23, 37"}},{"t":"usc","label":"12 U.S.C. § 248","url":"https://www.law.cornell.edu/uscode/text/12/248","stext":{"head":"§248. Enumerated powers","paras":[[0,"The Board of Governors of the Federal Reserve System shall be authorized and empowered:"],[0,"(a) Examination of accounts and affairs of banks; publication of weekly statements; reports of liabilities and assets of depository institutions; covered institutions"],[0,"(1) To examine at its discretion the accounts, books, and affairs of each Federal reserve bank and of each member bank and to require such statements and reports as it may deem necessary. The said board shall publish once each week a statement showing the condition of each Federal reserve bank and a consolidated statement for all Federal reserve banks. Such statements shall show in detail the assets and liabilities of the Federal reserve banks, single and combined, and shall furnish full information regarding the character of the money held as reserve and the amount, nature, and maturities of the paper and other investments owned or held by Federal reserve banks."],[0,"(2) To require any depository institution specified in this paragraph to make, at such intervals as the Board may prescribe, such reports of its liabilities and assets as the Board may determine to be necessary or desirable to enable the Board to discharge its responsibility to monitor and control monetary and credit aggregates. Such reports shall be made (A) directly to the Board in the case of member banks and in the case of other depository institutions whose reserve requirements under sections 461, 463, 464, 465, and 466 of this title exceed zero, and (B) for all other reports to the Board through the (i) Federal Deposit Insurance Corporation in the case of insured State savings associations that are insured depository institutions (as defined in section 1813 of this title), State nonmember banks, savings banks, and mutual savings banks, (ii) National Credit Union Administration Board in the case of insured credit unions, (iii) the Comptroller of the Currency in the case of any Federal savings association which is an insured depository institution (as defined in section 1813 of this title) or which is a member as defined in section 1422 of this title, and (iv) such State officer or agency as the Board may designate in the case of any other type of bank, savings association, or credit union. The Board shall endeavor to avoid the imposition of unnecessary burdens on reporting institutions and the duplication of other reporting requirements. Except as otherwise required by law, any data provided to any department, agency, or instrumentality of the United States pursuant to other reporting requirements shall be made available to the Board. The Board may classify depository institutions for the purposes of this paragraph and may impose different requirements on each such class."],[0,"(b) Permitting or requiring rediscounting of paper at specified rate"],[0,"To permit, or, on the affirmative vote of at least five members of the Board of Governors, to require Federal reserve banks to rediscount the discounted paper of other Federal reserve banks at rates of interest to be fixed by the Board."],[0,"(c) Suspending reserve requirements"],[0,"To suspend for a period not exceeding thirty days, and from time to time to renew such suspension for periods not exceeding fifteen days, any reserve requirements specified in this chapter."],[0,"(d) Supervising and regulating issue and retirement of notes"],[0,"To supervise and regulate through the Secretary of the Treasury the issue and retirement of Federal Reserve notes, except for the cancellation and destruction, and accounting with respect to such cancellation and destruction, of notes unfit for circulation, and to prescribe rules and regulations under which such notes may be delivered by the Secretary of the Treasury to the Federal Reserve agents applying therefor."],[0,"(e) Adding to or reclassifying reserve cities"],[0,"To add to the number of cities classified as reserve cities under existing law in which national banking associations are subject to the reserve requirements set forth in section 20 of this Act, or to reclassify existing reserve cities or to terminate their designation as such."],[0,"(f) Suspending or removing officers or directors of reserve banks"],[0,"To suspend or remove any officer or director of any Federal reserve bank, the cause of such removal to be forthwith communicated in writing by the Board of Governors of the Federal Reserve System to the removed officer or director and to said bank."],[0,"(g) Requiring writing off of doubtful or worthless assets of banks"],[0,"To require the writing off of doubtful or worthless assets upon the books and balance sheets of Federal reserve banks."],[0,"(h) Suspending operations of or liquidating or reorganizing banks"],[0,"To suspend, for the violation of any of the provisions of this chapter, the operations of any Federal reserve bank, to take possession thereof, administer the same during the period of suspension, and, when deemed advisable, to liquidate or reorganize such bank."],[0,"(i) Requiring bonds of agents; safeguarding property in hands of agents"],[0,"To require bonds of Federal reserve agents, to make regulations for the safeguarding of all collateral, bonds, Federal reserve notes, money, or property of any kind deposited in the hands of such agents, and said board shall perform the duties, functions, or services specified in this chapter, and make all rules and regulations necessary to enable said board effectively to perform the same."],[0,"(j) Exercising supervision over reserve banks"],[0,"To exercise general supervision over said Federal reserve banks."],[0,"(k) Delegation of certain functions; power to delegate; review of delegated activities"],[0,"To delegate, by published order or rule and subject to subchapter II of chapter 5, and chapter 7, of title 5, any of its functions, other than those relating to rulemaking or pertaining principally to monetary and credit policies, to one or more administrative law judges, members or employees of the Board, or Federal Reserve banks. The assignment of responsibility for the performance of any function that the Board determines to delegate shall be a function of the Chairman. The Board shall, upon the vote of one member, review action taken at a delegated level within such time and in such manner as the Board shall by rule prescribe. The Board of Governors may not delegate to a Federal reserve bank its functions for the establishment of policies for the supervision and regulation of depository institution holding companies and other financial firms supervised by the Board of Governors."],[0,"(l) Employing attorneys, experts, assistants, and clerks; salaries and fees"],[0,"To employ such attorneys, experts, assistants, clerks, or other employees as may be deemed necessary to conduct the business of the board. All salaries and fees shall be fixed in advance by said board and shall be paid in the same manner as the salaries of the members of said board. All such attorneys, experts, assistants, clerks, and other employees shall be appointed without regard to the provisions of the Act of January sixteenth, eighteen hundred and eighty-three (volume twenty-two, United States Statutes at Large, page four hundred and three), and amendments thereto, or any rule or regulation made in pursuance thereof: Provided, That nothing herein shall prevent the President from placing said employees in the classified service."],[0,"(m) [Repealed]"],[0,"(n) Board's authority to examine depository institutions and affiliates"],[0,"To examine, at the Board's discretion, any depository institution, and any affiliate of such depository institution, in connection with any advance to, any discount of any instrument for, or any request for any such advance or discount by, such depository institution under this chapter."],[0,"(o) Authority to appoint conservator or receiver"],[0,"The Board may appoint the Federal Deposit Insurance Corporation as conservator or receiver for a State member bank under section 1821(c)(9) of this title."],[0,"(p) Authority"],[0,"The Board may act in its own name and through its own attorneys in enforcing any provision of this title,1 regulations promulgated hereunder, or any other law or regulation, or in any action, suit, or proceeding to which the Board is a party and which involves the Board's regulation or supervision of any bank, bank holding company (as defined in section 1841 of this title), or other entity, or the administration of its operations."],[0,"(q) Uniform protection authority for Federal reserve facilities"],[0,"(1) Notwithstanding any other provision of law, to authorize personnel to act as law enforcement officers to protect and safeguard the premises, grounds, property, personnel, including members of the Board, of the Board, or any Federal reserve bank, and operations conducted by or on behalf of the Board or a reserve bank."],[0,"(2) The Board may, subject to the regulations prescribed under paragraph (5), delegate authority to a Federal reserve bank to authorize personnel to act as law enforcement officers to protect and safeguard the bank's premises, grounds, property, personnel, and operations conducted by or on behalf of the bank."],[0,"(3) Law enforcement officers designated or authorized by the Board or a reserve bank under paragraph (1) or (2) are authorized while on duty to carry firearms and make arrests without warrants for any offense against the United States committed in their presence, or for any felony cognizable under the laws of the United States committed or being committed within the buildings and grounds of the Board or a reserve bank if they have reasonable grounds to believe that the person to be arrested has committed or is committing such a felony. Such officers shall have access to law enforcement information that may be necessary for the protection of the property or personnel of the Board or a reserve bank."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/12/248?type=usc&year=mostrecent&link-type=html"},"head":"§248. Enumerated powers","tname":"Banks and Banking","by":{"0":"36","1":"37","2":"15"}},{"t":"usc","label":"12 U.S.C. § 263","url":"https://www.law.cornell.edu/uscode/text/12/263","by":{"0":"34","1":"38"}},{"t":"usc","label":"12 U.S.C. § 288","url":"https://www.law.cornell.edu/uscode/text/12/288","subs":["(a)(2)"],"by":{"0":"33"}},{"t":"usc","label":"12 U.S.C. § 289","url":"https://www.law.cornell.edu/uscode/text/12/289","subs":["(a)(3)(A)"],"by":{"0":"33"}},{"t":"usc","label":"12 U.S.C. § 341","url":"https://www.law.cornell.edu/uscode/text/12/341","stext":{"head":"§341. General enumeration of powers","paras":[[0,"Upon the filing of the organization certificate with the Comptroller of the Currency a Federal reserve bank shall become a body corporate and as such, and in the name designated in such organization certificate, shall have power—"],[0,"First. To adopt and use a corporate seal."],[0,"Second. To have succession after February 25, 1927, until dissolved by Act of Congress or until forfeiture of franchise for violation of law."],[0,"Third. To make contracts."],[0,"Fourth. To sue and be sued, complain and defend, in any court of law or equity."],[0,"Fifth. To appoint by its board of directors a president, vice presidents, and such officers and employees as are not otherwise provided for in this chapter, to define their duties, require bonds for them and fix the penalty thereof, and to dismiss at pleasure such officers or employees. The president shall be the chief executive officer of the bank and shall be appointed by the Class B and Class C directors of the bank, with the approval of the Board of Governors of the Federal Reserve System, for a term of 5 years; and all other executive officers and all employees of the bank shall be directly responsible to the president. The first vice president of the bank shall be appointed in the same manner and for the same term as the president, and shall, in the absence or disability of the president or during a vacancy in the office of president, serve as chief executive officer of the bank. Whenever a vacancy shall occur in the office of the president or the first vice president, it shall be filled in the manner provided for original appointments; and the person so appointed shall hold office until the expiration of the term of his predecessor."],[0,"Sixth. To prescribe by its board of directors, bylaws not inconsistent with law, regulating the manner in which its general business may be conducted, and the privileges granted to it by law may be exercised and enjoyed."],[0,"Seventh. To exercise by its board of directors, or duly authorized officers or agents, all powers specifically granted by the provisions of this chapter and such incidental powers as shall be necessary to carry on the business of banking within the limitations prescribed by this chapter."],[0,"Eighth. Upon deposit with the Treasurer of the United States of any bonds of the United States in the manner provided by existing law relating to national banks, to receive from the Secretary of the Treasury circulating notes in blank, registered and countersigned as provided by law, equal in amount to the par value of the bonds so deposited, such notes to be issued under the same conditions and provisions of law as relate to the issue of circulating notes of national banks secured by bonds of the United States bearing the circulating privilege, except that the issue of such notes shall not be limited to the capital stock of such Federal reserve bank."],[0,"But no Federal reserve bank shall transact any business except such as is incidental and necessarily preliminary to its organization until it has been authorized by the Comptroller of the Currency to commence business under the provisions of this chapter."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/12/341?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§341. General enumeration of powers","tname":"Banks and Banking","by":{"0":"34","1":"37"}},{"t":"usc","label":"12 U.S.C. § 342","url":"https://www.law.cornell.edu/uscode/text/12/342","by":{"0":"3"}},{"t":"usc","label":"12 U.S.C. § 355","url":"https://www.law.cornell.edu/uscode/text/12/355","by":{"0":"23, 33"}},{"t":"law","label":"Pub. L. No. 106-569","url":"https://www.govinfo.gov/link/plaw/106/public/569","by":{"0":"20"}},{"t":"usc","label":"12 U.S.C. § 2601","url":"https://www.law.cornell.edu/uscode/text/12/2601","by":{"0":"47"}},{"t":"usc","label":"15 U.S.C. § 1601","url":"https://www.law.cornell.edu/uscode/text/15/1601","by":{"0":"47"}},{"t":"usc","label":"15 U.S.C. § 1635","url":"https://www.law.cornell.edu/uscode/text/15/1635","by":{"0":"48"}},{"t":"usc","label":"15 U.S.C. § 1638","url":"https://www.law.cornell.edu/uscode/text/15/1638","by":{"0":"47"}},{"t":"usc","label":"8 U.S.C. § 1356","url":"https://www.law.cornell.edu/uscode/text/8/1356","subs":["(m)","(n)","(d)","(h)(1)(A)","(h)(1)(B)"],"stext":{"head":"§1356. Disposition of moneys collected under the provisions of this subchapter","paras":[[0,"(a) Detention, transportation, hospitalization, and all other expenses of detained aliens; expenses of landing stations"],[0,"All moneys paid into the Treasury to reimburse the Service for detention, transportation, hospitalization, and all other expenses of detained aliens paid from the appropriation for the enforcement of this chapter, and all moneys paid into the Treasury to reimburse the Service for expenses of landing stations referred to in section 1223(b) of this title paid by the Service from the appropriation for the enforcement of this chapter, shall be credited to the appropriation for the enforcement of this chapter for the fiscal year in which the expenses were incurred."],[0,"(b) Purchase of evidence"],[0,"Moneys expended from appropriations for the Service for the purchase of evidence and subsequently recovered shall be reimbursed to the current appropriation for the Service."],[0,"(c) Fees and administrative fines and penalties; exception"],[0,"Except as otherwise provided in subsection (a) and subsection (b), or in any other provision of this subchapter, all moneys received in payment of fees and administrative fines and penalties under this subchapter shall be covered into the Treasury as miscellaneous receipts: Provided, however, That all fees received from applicants residing in the Virgin Islands of the United States, and in Guam, required to be paid under section 1351 of this title, shall be paid over to the Treasury of the Virgin Islands and to the Treasury of Guam, respectively."],[0,"(d) Schedule of fees"],[0,"In addition to any other fee authorized by law, the Attorney General shall charge and collect $7 per individual for the immigration inspection of each passenger arriving at a port of entry in the United States, or for the preinspection of a passenger in a place outside of the United States prior to such arrival, aboard a commercial aircraft or commercial vessel."],[0,"(e) Limitations on fees"],[0,"(1) Except as provided in paragraph (3), no fee shall be charged under subsection (d) for immigration inspection or preinspection provided in connection with the arrival of any passenger, other than aircraft passengers, whose journey originated in the following:"],[1,"(A) Canada,"],[1,"(B) Mexico,"],[1,"(C) a State, territory or possession of the United States, or"],[1,"(D) any adjacent island (within the meaning of section 1101(b)(5) of this title)."],[0,"(2) No fee may be charged under subsection (d) with respect to the arrival of any passenger—"],[1,"(A) who is in transit to a destination outside the United States, and"],[1,"(B) for whom immigration inspection services are not provided."],[0,"(3) The Attorney General shall charge and collect $3 per individual for the immigration inspection or pre-inspection of each commercial vessel passenger whose journey originated in the United States or in any place set forth in paragraph (1): Provided, That this requirement shall not apply to immigration inspection at designated ports of entry of passengers arriving by ferry, or by Great Lakes vessels on the Great Lakes and connecting waterways when operating on a regular schedule. For the purposes of this paragraph, the term \"ferry\" means a vessel, in other than ocean or coastwise service, having provisions only for deck passengers and/or vehicles, operating on a short run on a frequent schedule between two points over the most direct water route, and offering a public service of a type normally attributed to a bridge or tunnel."],[0,"(f) Collection"],[0,"(1) Each person that issues a document or ticket to an individual for transportation by a commercial vessel or commercial aircraft into the United States shall—"],[1,"(A) collect from that individual the fee charged under subsection (d) at the time the document or ticket is issued; and"],[1,"(B) identify on that document or ticket the fee charged under subsection (d) as a Federal inspection fee."],[0,"(2) If—"],[1,"(A) a document or ticket for transportation of a passenger into the United States is issued in a foreign country; and"],[1,"(B) the fee charged under subsection (d) is not collected at the time such document or ticket is issued;"],[0,"the person providing transportation to such passenger shall collect such fee at the time such passenger departs from the United States and shall provide such passenger a receipt for the payment of such fee."],[0,"(3) The person who collects fees under paragraph (1) or (2) shall remit those fees to the Attorney General at any time before the date that is thirty-one days after the close of the calendar quarter in which the fees are collected, except the fourth quarter payment for fees collected from airline passengers shall be made on the date that is ten days before the end of the fiscal year, and the first quarter payment shall include any collections made in the preceding quarter that were not remitted with the previous payment. Regulations issued by the Attorney General under this subsection with respect to the collection of the fees charged under subsection (d) and the remittance of such fees to the Treasury of the United States shall be consistent with the regulations issued by the Secretary of the Treasury for the collection and remittance of the taxes imposed by subchapter C of chapter 33 of title 26, but only to the extent the regulations issued with respect to such taxes do not conflict with the provisions of this section."],[0,"(g) Provision of immigration inspection and preinspection services"],[0,"Notwithstanding section 1353b of this title, or any other provision of law, the immigration services required to be provided to passengers upon arrival in the United States on scheduled airline flights shall be adequately provided when needed and at no cost (other than the fees imposed under subsection (d)) to airlines and airline passengers at:"],[1,"(1) immigration serviced airports, and"],[1,"(2) places located outside of the United States at which an immigration officer is stationed for the purpose of providing such immigration services."],[0,"(h) Disposition of receipts"],[0,"(1)(A) There is established in the general fund of the Treasury a separate account which shall be known as the \"Immigration User Fee Account\". Notwithstanding any other section of this subchapter, there shall be deposited as offsetting receipts into the Immigration User Fee Account all fees collected under subsection (d) of this section, to remain available until expended..1 At the end of each 2-year period, beginning with the creation of this account, the Attorney General, following a public rulemaking with opportunity for notice and comment, shall submit a report to the Congress concerning the status of the account, including any balances therein, and recommend any adjustment in the prescribed fee that may be required to ensure that the receipts collected from the fee charged for the succeeding two years equal, as closely as possible, the cost of providing these services."],[0,"(B) Notwithstanding any other provisions of law, all civil fines or penalties collected pursuant to sections 1253(c), 1321, and 1323 of this title and all liquidated damages and expenses collected pursuant to this chapter shall be deposited in the Immigration User Fee Account."],[0,"(2)(A) The Secretary of the Treasury shall refund out of the Immigration User Fee Account to any appropriation the amount paid out of such appropriation for expenses incurred by the Attorney General in providing immigration inspection and preinspection services for commercial aircraft or vessels and in—"],[1,"(i) providing overtime immigration inspection services for commercial aircraft or vessels;"],[1,"(ii) administration of debt recovery, including the establishment and operation of a national collections office;"],[1,"(iii) expansion, operation and maintenance of information systems for nonimmigrant control and debt collection;"],[1,"(iv) detection of fraudulent documents used by passengers traveling to the United States, including training of, and technical assistance to, commercial airline personnel regarding such detection;"],[1,"(v) providing detention and removal services for inadmissible aliens arriving on commercial aircraft and vessels and for any alien who is inadmissible under section 1182(a) of this title who has attempted illegal entry into the United States through avoidance of immigration inspection at air or sea ports-of-entry; and"],[1,"(vi) providing removal and asylum proceedings at air or sea ports-of-entry for inadmissible aliens arriving on commercial aircraft and vessels including immigration removal proceedings resulting from presentation of fraudulent documents and failure to present documentation and for any alien who is inadmissible under section 1182(a) of this title who has attempted illegal entry into the United States through avoidance of immigration inspection at air or sea ports-of-entry."],[0,"The Attorney General shall provide for expenditures for training and assistance described in clause (iv) in an amount, for any fiscal year, not less than 5 percent of the total of the expenses incurred that are described in the previous sentence."],[0,"(B) The amounts which are required to be refunded under subparagraph (A) shall be refunded at least quarterly on the basis of estimates made by the Attorney General of the expenses referred to in subparagraph (A). Proper adjustments shall be made in the amounts subsequently refunded under subparagraph (A) to the extent prior estimates were in excess of, or less than, the amount required to be refunded under subparagraph (A)."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1356?type=usc&year=mostrecent&link-type=html"},"head":"§1356. Disposition of moneys collected under the provisions of this subchapter","tname":"Aliens and Nationality","by":{"0":"23, 23, 23","1":"35","2":"17, 17, 17"}},{"t":"usc","label":"12 U.S.C. § 16","url":"https://www.law.cornell.edu/uscode/text/12/16","stext":{"head":"§16. Funding of Office","paras":[[0,"The Comptroller of the Currency may collect an assessment, fee, or other charge from any entity described in section 1813(q)(1) of this title, as the Comptroller determines is necessary or appropriate to carry out the responsibilities of the Office of the Comptroller of the Currency. In establishing the amount of an assessment, fee, or charge collected from an entity under this section, the Comptroller of the Currency may take into account the nature and scope of the activities of the entity, the amount and type of assets that the entity holds, the financial and managerial condition of the entity, and any other factor, as the Comptroller of the Currency determines is appropriate. Funds derived from any assessment, fee, or charge collected or payment made pursuant to this section may be deposited by the Comptroller of the Currency in accordance with the provisions of section 192 of this title. Such funds shall not be construed to be Government funds or appropriated monies, and shall not be subject to apportionment for purposes of chapter 15 of title 31 or any other provision of law. The authority of the Comptroller of the Currency under this section shall be in addition to the authority under subchapter XV of chapter 3."],[0,"The Comptroller of the Currency shall have sole authority to determine the manner in which the obligations of the Office of the Comptroller of the Currency shall be incurred and its disbursements and expenses allowed and paid, in accordance with this section, except as provided in chapter 71 of title 5 (with respect to compensation)."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/12/16?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§16. Funding of Office","tname":"Banks and Banking","by":{"0":"23, 30, 32, 37","2":"3"}},{"t":"usc","label":"12 U.S.C. § 192","url":"https://www.law.cornell.edu/uscode/text/12/192","by":{"0":"32"}},{"t":"usc","label":"12 U.S.C. § 481","url":"https://www.law.cornell.edu/uscode/text/12/481","by":{"0":"23, 32, 37"}},{"t":"usc","label":"12 U.S.C. § 482","url":"https://www.law.cornell.edu/uscode/text/12/482","by":{"0":"23"}},{"t":"usc","label":"12 U.S.C. § 4516","url":"https://www.law.cornell.edu/uscode/text/12/4516","stext":{"head":"§4516. Funding","paras":[[0,"(a) Annual assessments"],[0,"The Director shall establish and collect from the regulated entities annual assessments in an amount not exceeding the amount sufficient to provide for reasonable costs (including administrative costs) and expenses of the Agency, including—"],[1,"(1) the expenses of any examinations under section 4517 of this title and under section 1440 of this title;"],[1,"(2) the expenses of obtaining any reviews and credit assessments under section 4519 of this title;"],[1,"(3) such amounts in excess of actual expenses for any given year as deemed necessary by the Director to maintain a working capital fund in accordance with subsection (e); and"],[1,"(4) the windup of the affairs of the Office of Federal Housing Enterprise Oversight and the Federal Housing Finance Board under title III of the Federal Housing Finance Regulatory Reform Act of 2008."],[0,"(b) Allocation of annual assessment to enterprises"],[0,"(1) Amount of payment"],[1,"Each enterprise shall pay to the Director a proportion of the annual assessment made pursuant to subsection (a) that bears the same ratio to the total annual assessment that the total assets of each enterprise bears 1 to the total assets of both enterprises."],[0,"(2) Separate treatment of Federal home loan bank and enterprise assessments"],[1,"Assessments collected from the enterprises shall not exceed the amounts sufficient to provide for the costs and expenses described in subsection (a) relating to the enterprises. Assessments collected from the Federal Home Loan Banks shall not exceed the amounts sufficient to provide for the costs and expenses described in subsection (a) relating to the Federal Home Loan Banks."],[0,"(3) Timing of payment"],[1,"The annual assessment shall be payable semiannually for each fiscal year, on October 1 and April 1."],[0,"(4) \"Total assets\" defined"],[1,"For the purpose of this section, the term \"total assets\" means, with respect to an enterprise, the sum of—"],[2,"(A) on-balance-sheet assets of the enterprise, as determined in accordance with generally accepted accounting principles;"],[2,"(B) the unpaid principal balance of outstanding mortgage-backed securities issued or guaranteed by the enterprise that are not included in subparagraph (A); and"],[2,"(C) other off-balance-sheet obligations as determined by the Director."],[0,"(c) Increased costs of regulation"],[0,"(1) Increase for inadequate capitalization"],[1,"The semiannual payments made pursuant to subsection (b) by any regulated entity that is not classified (for purposes of subchapter II) as adequately capitalized may be increased, as necessary, in the discretion of the Director to pay additional estimated costs of regulation of the regulated entity."],[0,"(2) Adjustment for enforcement activities"],[1,"The Director may adjust the amounts of any semiannual payments for an assessment under subsection (a) that are to be paid pursuant to subsection (b) by a regulated entity, as necessary in the discretion of the Director, to ensure that the costs of enforcement activities under this Act for a regulated entity are borne only by such regulated entity."],[0,"(3) Additional assessment for deficiencies"],[1,"If at any time, as a result of increased costs of regulation of a regulated entity that is not classified (for purposes of subchapter II) as adequately capitalized or as the result of supervisory or enforcement activities under this Act for a regulated entity, the amount available from any semiannual payment made by such regulated entity pursuant to subsection (b) is insufficient to cover the costs of the Agency with respect to such entity, the Director may make and collect from such regulated entity an immediate assessment to cover the amount of such deficiency for the semiannual period. If, at the end of any semiannual period during which such an assessment is made, any amount remains from such assessment, such remaining amount shall be deducted from the assessment for such regulated entity for the following semiannual period."],[0,"(d) Surplus"],[0,"Except with respect to amounts collected pursuant to subsection (a)(3), if any amount from any annual assessment collected from an enterprise remains unobligated at the end of the year for which the assessment was collected, such amount shall be credited to the assessment to be collected from the enterprise for the following year."],[0,"(e) Working capital fund"],[0,"At the end of each year for which an assessment under this section is made, the Director shall remit to each regulated entity any amount of assessment collected from such regulated entity that is attributable to subsection (a)(3) and is in excess of the amount the Director deems necessary to maintain a working capital fund."],[0,"(f) Treatment of assessments"],[0,"(1) Deposit"],[1,"Amounts received by the Director from assessments under this section may be deposited by the Director in the manner provided in section 192 of this title for monies deposited by the Comptroller of the Currency."],[0,"(2) Not Government funds"],[1,"The amounts received by the Director from any assessment under this section shall not be construed to be Government or public funds or appropriated money."],[0,"(3) No apportionment of funds"],[1,"Notwithstanding any other provision of law, the amounts received by the Director from any assessment under this section shall not be subject to apportionment for the purpose of chapter 15 of title 31 or under any other authority."],[0,"(4) Use of funds"],[1,"The Director may use any amounts received by the Director from assessments under this section for compensation of the Director and other employees of the Agency and for all other expenses of the Director and the Agency."],[0,"(5) Availability of oversight fund amounts"],[1,"Notwithstanding any other provision of law, any amounts remaining in the Federal Housing Enterprises Oversight Fund established under this section (as in effect before the effective date of the Federal Housing Finance Regulatory Reform Act of 2008, and any amounts remaining from assessments on the Federal Home Loan Banks pursuant to section 1438(b) 2 of this title), shall, upon such effective date, be treated for purposes of this subsection as amounts received from assessments under this section."],[0,"(6) Treasury investments"],[0,"(A) Authority"],[2,"The Director may request the Secretary of the Treasury to invest such portions of amounts received by the Director from assessments paid under this section that, in the Director's discretion, are not required to meet the current working needs of the Agency."],[0,"(B) Government obligations"],[2,"Pursuant to a request under subparagraph (A), the Secretary of the Treasury shall invest such amounts in Government obligations guaranteed as to principal and interest by the United States with maturities suitable to the needs of the Agency and bearing interest at a rate determined by the Secretary of the Treasury taking into consideration current market yields on outstanding marketable obligations of the United States of comparable maturity."],[0,"(g) Budget and financial management"],[0,"(1) Financial operating plans and forecasts"],[1,"The Director shall provide to the Director of the Office of Management and Budget copies of the Director's financial operating plans and forecasts, as prepared by the Director in the ordinary course of the Agency's operations, and copies of the quarterly reports of the Agency's financial condition and results of operations, as prepared by the Director in the ordinary course of the Agency's operations."],[0,"(2) Financial statements"],[1,"The Agency shall prepare annually a statement of—"],[2,"(A) assets and liabilities and surplus or deficit;"],[2,"(B) income and expenses; and"],[2,"(C) sources and application of funds."],[0,"(3) Financial management systems"],[1,"The Agency shall implement and maintain financial management systems that—"],[2,"(A) comply substantially with Federal financial management systems requirements and applicable Federal accounting standards; and"],[2,"(B) use a general ledger system that accounts for activity at the transaction level."],[0,"(4) Assertion of internal controls"],[1,"The Director shall provide to the Comptroller General of the United States an assertion as to the effectiveness of the internal controls that apply to financial reporting by the Agency, using the standards established in section 3512(c) of title 31."],[0,"(5) Rule of construction"],[1,"This subsection may not be construed as implying any obligation on the part of the Director to consult with or obtain the consent or approval of the Director of the Office of Management and Budget with respect to any report, plan, forecast, or other information referred to in paragraph (1) or any jurisdiction or oversight over the affairs or operations of the Agency."],[0,"(h) Audit of Agency"],[0,"(1) In general"],[1,"The Comptroller General shall annually audit the financial transactions of the Agency in accordance with the United States generally accepted government auditing standards as may be prescribed by the Comptroller General of the United States. The audit shall be conducted at the place or places where accounts of the Agency are normally kept. The representatives of the Government Accountability Office shall have access to the personnel and to all books, accounts, documents, papers, records (including electronic records), reports, files, and all other papers, automated data, things, or property belonging to or under the control of or used or employed by the Agency pertaining to its financial transactions and necessary to facilitate the audit, and such representatives shall be afforded full facilities for verifying transactions with the balances or securities held by depositories, fiscal agents, and custodians. All such books, accounts, documents, records, reports, files, papers, and property of the Agency shall remain in possession and custody of the Agency. The Comptroller General may obtain and duplicate any such books, accounts, documents, records, working papers, automated data and files, or other information relevant to such audit without cost to the Comptroller General and the Comptroller General's right of access to such information shall be enforceable pursuant to section 716(c) of title 31."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/12/4516?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§4516. Funding","tname":"Banks and Banking","by":{"0":"23"}},{"t":"usc","label":"19 U.S.C. § 58c","url":"https://www.law.cornell.edu/uscode/text/19/58c","stext":{"head":"§58c. Fees for certain customs services","paras":[[0,"(a) Schedule of fees"],[0,"In addition to any other fee authorized by law, the Secretary of the Treasury shall charge and collect the following fees (subject to adjustment under subsection (l)) for the provision of customs services in connection with the following:"],[1,"(1) For the arrival of a commercial vessel of 100 net tons or more, $397."],[1,"(2) For the arrival of a commercial truck, $5."],[1,"(3) For the arrival of each railroad car carrying passengers or commercial freight, $7.50."],[1,"(4) For all arrivals made during a calendar year by a private vessel or private aircraft, $25."],[1,"(5)(A) Subject to subparagraph (B), for the arrival of each passenger aboard a commercial vessel or commercial aircraft from a place outside the United States (other than a place referred to in subsection (b)(1)(A)(i) of this section), $5."],[1,"(B) For the arrival of each passenger aboard a commercial vessel from a place referred to in subsection (b)(1)(A)(i) of this section, $1.75."],[1,"(6) For each item of dutiable mail for which a document is prepared by a customs officer (other than an item subject to a fee under subsection (b)(9)(D)), $5."],[1,"(7) For each customs broker permit held by an individual, partnership, association, or corporate customs broker, $125 per year."],[1,"(8) For the arrival of a barge or other bulk carrier from Canada or Mexico, $100."],[1,"(9)(A) For the processing of merchandise that is formally entered or released during any fiscal year, a fee in an amount equal to 0.21 1 percent ad valorem, unless adjusted under subparagraph (B)."],[1,"(B)(i) The Secretary of the Treasury may adjust the ad valorem rate specified in subparagraph (A) to an ad valorem rate (but not to a rate of more than 0.21 1 percent nor less than 0.15 percent) and the amounts specified in subsection (b)(8)(A)(i) (but not to more than $485 nor less than $21) to rates and amounts which would, if charged, offset the salaries and expenses that will likely be incurred by the Customs Service in the processing of such entries and releases during the fiscal year in which such costs are incurred."],[1,"(ii) In determining the amount of any adjustment under clause (i), the Secretary of the Treasury shall take into account whether there is a surplus or deficit in the fund established under subsection (f) with respect to the provision of customs services for the processing of formal entries and releases of merchandise."],[1,"(iii) An adjustment may not be made under clause (i) with respect to the fee charged during any fiscal year unless the Secretary of the Treasury—"],[2,"(I) not later than 45 days after the date of the enactment of the Act providing full-year appropriations for the Customs Service for that fiscal year, publishes in the Federal Register a notice of intent to adjust the fee under this paragraph and the amount of such adjustment;"],[2,"(II) provides a period of not less than 30 days following publication of the notice described in subclause (I) for public comment and consultation with the Committee on Finance of the Senate and the Committee on Ways and Means of the House of Representatives regarding the proposed adjustment and the methodology used to determine such adjustment;"],[2,"(III) upon the expiration of the period provided under subclause (II), notifies such committees in writing regarding the final determination to adjust the fee, the amount of such adjustment, and the methodology used to determine such adjustment; and"],[2,"(IV) upon the expiration of the 15-day period following the written notification described in subclause (III), submits for publication in the Federal Register notice of the final determination regarding the adjustment of the fee."],[1,"(iv) The 15-day period referred to in clause (iii)(IV) shall be computed by excluding—"],[2,"(I) the days on which either House is not in session because of an adjournment of more than 3 days to a day certain or an adjournment of the Congress sine die; and"],[2,"(II) any Saturday and Sunday, not excluded under subclause (I), when either House is not in session."],[1,"(v) An adjustment made under this subparagraph shall become effective with respect to formal entries and releases made on or after the 15th calendar day after the date of publication of the notice described in clause (iii)(IV) and shall remain in effect until adjusted under this subparagraph."],[1,"(C) Any fee charged under this paragraph, whether or not adjusted under subparagraph (B), is subject to the limitations in subsection (b)(8)(A)."],[1,"(10) For the processing of merchandise that is informally entered or released, other than at—"],[2,"(A) a centralized hub facility,"],[2,"(B) an express consignment carrier facility, or"],[2,"(C) a small airport or other facility to which section 58b of this title applies, if more than 25,000 informal entries were cleared through such airport or facility during the fiscal year preceding such entry or release (other than Inbound EMS items described in subsection (b)(9)(D)),"],[1,"a fee of—"],[2,"(i) $2 if the entry or release is automated and not prepared by customs personnel;"],[2,"(ii) $6 if the entry or release is manual and not prepared by customs personnel; or"],[2,"(iii) $9 if the entry or release, whether automated or manual, is prepared by customs personnel."],[1,"For provisions relating to the informal entry or release of merchandise at facilities referred to in subparagraphs (A), (B), and (C), or of Inbound EMS items described in subsection (b)(9)(D), see subsection (b)(9)."],[0,"(b) Limitations on fees"],[0,"(1)(A) Except as provided in subsection (a)(5)(B) of this section, no fee may be charged under subsection (a) of this section for customs services provided in connection with—"],[1,"(i) the arrival of any passenger whose journey—"],[2,"(I) originated in a territory or possession of the United States; or"],[2,"(II) originated in the United States and was limited to territories and possessions of the United States;"],[1,"(ii) the arrival of any railroad car the journey of which originates and terminates in the same country, but only if no passengers board or disembark from the train and no cargo is loaded or unloaded from such car while the car is within any country other than the country in which such car originates and terminates;"],[1,"(iii) the arrival of a ferry, except for a ferry whose operations begin on or after August 1, 1999, and that operates south of 27 degrees latitude and east of 89 degrees longitude; or"],[1,"(iv) the arrival of any passenger on board a commercial vessel traveling only between ports which are within the customs territory of the United States."],[0,"(B) The exemption provided for in subparagraph (A) shall not apply in the case of the arrival of any passenger on board a commercial vessel whose journey originates and terminates at the same place in the United States if there are no intervening stops."],[0,"(C) The exemption provided for in subparagraph (A)(i) shall not apply to fiscal years 1994, 1995, 1996, and 1997."],[0,"(2) No fee may be charged under subsection (a)(2) for the arrival of a commercial truck during any calendar year after a total of $100 in fees (subject to adjustment under subsection (l)) has been paid to the Secretary of the Treasury for the provision of customs services for all arrivals of such commercial truck during such calendar year."],[0,"(3) No fee may be charged under subsection (a)(3) for the arrival of a railroad car whether passenger or freight during any calendar year after a total of $100 in fees (subject to adjustment under subsection (l)) has been paid to the Secretary of the Treasury for the provision of customs services for all arrivals of such passenger or freight rail car during such calendar year."],[0,"(4)(A) No fee may be charged under subsection (a)(5) with respect to the arrival of any passenger—"],[1,"(i) who is in transit to a destination outside the customs territory of the United States, and"],[1,"(ii) for whom customs inspectional services are not provided."],[0,"(B) In the case of a commercial vessel making a single voyage involving 2 or more United States ports with respect to which the passengers would otherwise be charged a fee pursuant to subsection (a)(5), such fee shall be charged only 1 time for each passenger."],[0,"(5) No fee may be charged under subsection (a)(1) for the arrival of—"],[1,"(A) a vessel during a calendar year after a total of $5,955 in fees (subject to adjustment under subsection (l)) charged under paragraph (1) or (8) of subsection (a) has been paid to the Secretary of the Treasury for the provision of customs services for all arrivals of such vessel during such calendar year,"],[1,"(B) any vessel which, at the time of the arrival, is being used solely as a tugboat, or"],[1,"(C) any barge or other bulk carrier from Canada or Mexico."],[0,"(6) No fee may be charged under subsection (a)(8) for the arrival of a barge or other bulk carrier during a calendar year after a total of $1,500 in fees (subject to adjustment under subsection (l)) charged under paragraph (1) or (8) of subsection (a) has been paid to the Secretary of the Treasury for the provision of customs services for all arrivals of such barge or other bulk carrier during such calendar year."],[0,"(7) No fee may be charged under paragraph (2), (3), or (4) of subsection (a) for the arrival of any—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/19/58c?type=usc&year=mostrecent&link-type=html"},"head":"§58c. Fees for certain customs services","tname":"Customs Duties","by":{"0":"23, 31","1":"35","2":"17, 17, 17"}},{"t":"usc","label":"20 U.S.C. § 54","url":"https://www.law.cornell.edu/uscode/text/20/54","by":{"0":"20"}},{"t":"usc","label":"20 U.S.C. § 1070h","url":"https://www.law.cornell.edu/uscode/text/20/1070h","op":1,"tname":"Education","by":{"0":"21"}},{"t":"usc","label":"21 U.S.C. § 136a","url":"https://www.law.cornell.edu/uscode/text/21/136a","subs":["(a)"],"by":{"0":"24, 31","1":"35"}},{"t":"usc","label":"31 U.S.C. § 1304","url":"https://www.law.cornell.edu/uscode/text/31/1304","subs":["(a)"],"by":{"0":"21","2":"4"}},{"t":"usc","label":"31 U.S.C. § 1305","url":"https://www.law.cornell.edu/uscode/text/31/1305","subs":["(2)"],"by":{"0":"21","2":"4"}},{"t":"usc","label":"31 U.S.C. § 5136","url":"https://www.law.cornell.edu/uscode/text/31/5136","by":{"0":"31"}},{"t":"usc","label":"35 U.S.C. § 41","url":"https://www.law.cornell.edu/uscode/text/35/41","by":{"0":"31"}},{"t":"usc","label":"42 U.S.C. § 301","url":"https://www.law.cornell.edu/uscode/text/42/301","by":{"0":"21","2":"4"}},{"t":"usc","label":"42 U.S.C. § 401","url":"https://www.law.cornell.edu/uscode/text/42/401","subs":["(b)","(a)"],"by":{"0":"21","2":"4, 4"}},{"t":"reg","label":"82 Fed. Reg. 54,472","url":"https://www.govinfo.gov/link/fr/82/54472","by":{"0":"5","1":"7"}},{"t":"reg","label":"84 Fed. Reg. 4252","url":"https://www.govinfo.gov/link/fr/84/4252","by":{"0":"6"}},{"t":"reg","label":"85 Fed. Reg. 41,905","url":"https://www.govinfo.gov/link/fr/85/41905","by":{"0":"6","1":"7"}},{"t":"reg","label":"85 Fed. Reg. 44,382","url":"https://www.govinfo.gov/link/fr/85/44382","by":{"0":"6","1":"7"}},{"t":"case","label":"A. L. A. Schechter Poultry Corp. v. United States","cite":"295 U.S. 495","y":1935,"id":"1900-1940/295us495","sc":1,"sum":"The Court held that the legislative branch cannot delegate to the President the authority to regulate industries without also providing standards or rules for doing so.","sumSrc":"Oyez","by":{"1":"29"}},{"t":"case","label":"Abbott Labs. v. Gardner","cite":"387 U.S. 136","y":1967,"id":"1966/39","sc":1,"sum":"The Court found that congress did not intend to forbid pre-enforcement review of regulations like the \"every time\" rule. The legislature designed the statute's specific review provisions to provide additional remedies for parties in Abbott Laboratories' position, not to cut down traditional channels of review. The Court remanded the case to the court of appeals.","sumSrc":"Oyez","by":{"1":"50–51"}},{"t":"case","label":"Financial Oversight & Mgmt. Bd. for P.R. v. Aurelius Inv., LLC","cite":"140 S. Ct. 1649","y":2020,"id":"2019/18-1334","sc":1,"sum":"A group of cases in which the Court will decide the constitutionality of President Barack Obama’s appointments (without their being confirmed by the Senate) to the oversight board created to help Puerto Rico recover from its substantial indebtedness.","sumSrc":"Oyez","by":{"1":"6, 42"}},{"t":"case","label":"Gundy v. United States","cite":"139 S. Ct. 2116","y":2019,"id":"2018/17-6086","sc":1,"op":1,"ar":1,"sum":"The Second Circuit’s judgment that 34 U. S. C. §20913(d)—which requires the Attorney General to apply the Sex Offender Registration and Notification Act’s registration requirements as soon as feasible to offenders convicted before the statute’s enactment—is not an unconstitutional delegation of legislative authority is affirmed.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"28–30"}},{"t":"case","label":"Health & Hosp. Corp. of Marion Cnty. v. Talevski","cite":"2023 WL 3872515","y":2023,"court":"U.S. June 8","by":{"1":"48"}},{"t":"case","label":"INS v. Chadha","cite":"462 U.S. 919","y":1983,"id":"1981/80-1832","sc":1,"sum":"The Court held that the Immigration and Nationality Act violated the separation of powers by allowing a one-house veto over executive decisions.","sumSrc":"Oyez","by":{"1":"20, 29"}},{"t":"case","label":"Kramer v. Union Free Sch. Dist. No. 15","cite":"395 U.S. 621","y":1969,"id":"1968/258","sc":1,"sum":"While the statute purported to limit voting rights to those who were \"primarily interested\" in the election's outcome, the Court found the structure of the law too broad to achieve this goal.","sumSrc":"Oyez","by":{"1":"43"}},{"t":"case","label":"Lucia v. SEC","cite":"138 S. Ct. 2044","y":2018,"id":"2017/17-130","sc":1,"sum":"The Court decided that administrative law judges of the Securities and Exchange Commission are \"officers of the United States\" subject to the Constitution's Appointments Clause.","sumSrc":"Oyez","by":{"1":"47–48, 50","2":"22"}},{"t":"case","label":"Mistretta v. United States","cite":"488 U.S. 361","y":1989,"id":"1988/87-7028","sc":1,"sum":"The Court found the Act to be valid because although Congress cannot generally delegate its legislative power to another Branch, the nondelegation doctrine does not prevent Congress from obtaining assistance from coordinate Branches.","sumSrc":"Oyez","by":{"1":"28–29"}},{"t":"case","label":"Morrison v. Olson","cite":"487 U.S. 654","y":1988,"id":"1987/87-1279","sc":1,"sum":"The near-unanimous Court held that the means of selecting the independent counsel did not violate the Appointments Clause; the powers allocated to the special court did not violate Article III; and the Act was not offensive to the separation of powers doctrine since it did not impermissibly interfere with the functions of the Executive Branch.","sumSrc":"Oyez","by":{"1":"24"}},{"t":"case","label":"N. Pipeline Constr. Co. v. Marathon Pipe Line Co.","cite":"458 U.S. 50","y":1982,"id":"1981/81-150","sc":1,"ar":1,"sum":"A plurality held that Congress had essentially conferred Article III powers to an adjunct system of courts and, consequently, \"impermissibly removed most, if not all, of the essential attributes of the judicial power\" from the district courts.","sumSrc":"Oyez","by":{"1":"51"}},{"t":"case","label":"Nat’l Fed’n of Indep. Bus. v. Sebelius","cite":"567 U.S. 519","y":2012,"id":"2011/11-393","sc":1,"sum":"Cases in which the Court held that the minimum coverage requirement of the Affordable Care Act was constitutional, that Congress had the power to enforce the taxation of most Americans that did not buy the minimum level of coverage, and that the federal government exceeded its power by pressuring States into accepting conditions that Congress could not impose directly by threatening to withhold all federal funding under Medicaid.","sumSrc":"Oyez","by":{"1":"43"}},{"t":"case","label":"Nixon v. Fitzgerald","cite":"457 U.S. 731","y":1982,"id":"1981/79-1738","sc":1,"sum":"The Court held that the President \"is entitled to absolute immunity from damages liability predicated on his official acts.\" This sweeping immunity, argued Justice Powell, was a function of the \"President's unique office, rooted in the constitutional tradition of separation of powers and supported by our history.\".","sumSrc":"Oyez","by":{"1":"21"}},{"t":"case","label":"Randall v. Sorrell","cite":"548 U.S. 230","y":2006,"id":"2005/04-1528","sc":1,"sum":"The opinion by Justice Stephen Breyer held that the Court should let stand the Buckley decision and its invalidation of expenditure limits. Vermont's argument that such limits prevent candidates from spending too much time fund-raising was deemed irrelevant because it was \"perfectly obvious\" and would not have changed the result in Buckley .","sumSrc":"Oyez","by":{"1":"44–45"}},{"t":"case","label":"Ryder v. United States","cite":"515 U.S. 177","y":1995,"id":"1994/94-431","sc":1,"sum":"The Court held that the judges' actions were not valid de facto. The Court reasoned that a defendant who made a timely challenge to the constitutional validity of the appointment of an officer who adjudicates his case was entitled to a decision on the merits of the question and whatever relief may be appropriate if a violation had occurred.","sumSrc":"Oyez","by":{"1":"49–51","2":"22, 23"}},{"t":"case","label":"United States v. Gentile","cite":"2017 WL 1437532","y":2017,"court":"E.D. Cal. Apr. 24","sum":"Noting that “vacat[ing] defendant’s convictions” would be “appropriate remedy” for violation of rider prohibiting expenditure of funds on certain medical-marijuana prosecutions.","sumSrc":"brief:1","by":{"1":"49"}},{"t":"case","label":"United States v. Richardson","cite":"418 U.S. 166","y":1974,"id":"1973/72-885","sc":1,"op":1,"sum":"The Court held that Richardson did not have standing to sue. Using the two-pronged standing test of Flast v. Cohen (1968), Chief Justice Burger found that there was no \"logical nexus between the status asserted [by Richardson as a taxpayer] and the claim sought to be adjudicated.\" It was clear to Burger that Richardson was not \"a proper and appropriate party to invoke federal judicial power\" on this issue.","sumSrc":"Oyez","by":{"1":"15"}},{"t":"case","label":"Va. Office for Prot. & Advoc. v. Stewart","cite":"563 U.S. 247","y":2011,"id":"2010/09-529","sc":1,"ar":6,"sum":"The Court held that a federal court may hear a lawsuit for prospective injunctive relief against state officials brought by another agency of the same state.","sumSrc":"Oyez","by":{"1":"49"}},{"t":"case","label":"Webster v. Doe","cite":"486 U.S. 592","y":1988,"id":"1987/86-1294","sc":1,"op":1,"sum":"Section 102(c) of the National Security Act of 1947 (NSA) authorizes the Director of the Central Intelligence Agency (CIA), \"in his discretion,\" to terminate the employment of any CIA employee \"whenever he shall deem such termination necessary or advisable in the interests of the United States.\" After respondent, a covert electronics technician in the CIA's employ, voluntarily informed the agency that he was a …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"29"}},{"t":"case","label":"Whitman v. Am. Trucking Ass’ns","cite":"531 U.S. 457","y":2001,"id":"2000/99-1257","sc":1,"sum":"The Court held that the CAA properly delegated legislative power to the EPA, but that the EPA could not consider implementation costs in setting primary and secondary NAAQS.","sumSrc":"Oyez","by":{"1":"27–31, 39","2":"10"}},{"t":"const","label":"Article I, Section 8, Clause 12","text":"To raise and support Armies, but no Appropriation of Money to that Use shall be for a longer Term than two Years;","by":{"1":"21"}},{"t":"const","label":"Article I, Section 9, Clause 7","clauses":[["appropriations","Appropriations Clause"]],"text":"No Money shall be drawn from the Treasury, but in Consequence of Appropriations made by Law; and a regular Statement and Account of the Receipts and Expenditures of all public Money shall be published from time to time.","by":{"1":"1, 9, 11, 16, 25"}},{"t":"usc","label":"5 U.S.C. § 706","url":"https://www.law.cornell.edu/uscode/text/5/706","by":{"1":"3, 10, 47–48"}},{"t":"usc","label":"12 U.S.C. § 248a","url":"https://www.law.cornell.edu/uscode/text/12/248a","by":{"1":"37"}},{"t":"usc","label":"12 U.S.C. § 321","url":"https://www.law.cornell.edu/uscode/text/12/321","by":{"1":"37"}},{"t":"usc","label":"12 U.S.C. § 328","url":"https://www.law.cornell.edu/uscode/text/12/328","by":{"1":"37"}},{"t":"usc","label":"12 U.S.C. § 371b","url":"https://www.law.cornell.edu/uscode/text/12/371b","by":{"1":"38"}},{"t":"usc","label":"28 U.S.C. § 2401","url":"https://www.law.cornell.edu/uscode/text/28/2401","by":{"1":"51"}},{"t":"usc","label":"35 U.S.C. § 42","url":"https://www.law.cornell.edu/uscode/text/35/42","stext":{"head":"§42. Patent and Trademark Office funding","paras":[[0,"(a) All fees for services performed by or materials furnished by the Patent and Trademark Office will be payable to the Director."],[0,"(b) All fees paid to the Director and all appropriations for defraying the costs of the activities of the Patent and Trademark Office will be credited to the Patent and Trademark Office Appropriation Account in the Treasury of the United States."],[0,"(c)(1) To the extent and in the amounts provided in advance in appropriations Acts, fees authorized in this title or any other Act to be charged or established by the Director shall be collected by and shall, subject to paragraph (3), be available to the Director to carry out the activities of the Patent and Trademark Office."],[0,"(2) There is established in the Treasury a Patent and Trademark Fee Reserve Fund. If fee collections by the Patent and Trademark Office for a fiscal year exceed the amount appropriated to the Office for that fiscal year, fees collected in excess of the appropriated amount shall be deposited in the Patent and Trademark Fee Reserve Fund. To the extent and in the amounts provided in appropriations Acts, amounts in the Fund shall be made available until expended only for obligation and expenditure by the Office in accordance with paragraph (3)."],[0,"(3)(A) Any fees that are collected under this title, and any surcharges on such fees, may only be used for expenses of the Office relating to the processing of patent applications and for other activities, services, and materials relating to patents and to cover a proportionate share of the administrative costs of the Office."],[0,"(B) Any fees that are collected under section 31 of the Trademark Act of 1946, and any surcharges on such fees, may only be used for expenses of the Office relating to the processing of trademark registrations and for other activities, services, and materials relating to trademarks and to cover a proportionate share of the administrative costs of the Office."],[0,"(d) The Director may refund any fee paid by mistake or any amount paid in excess of that required."],[0,"(e) The Secretary of Commerce shall, on the day each year on which the President submits the annual budget to the Congress, provide to the Committees on the Judiciary of the Senate and the House of Representatives—"],[1,"(1) a list of patent and trademark fee collections by the Patent and Trademark Office during the preceding fiscal year;"],[1,"(2) a list of activities of the Patent and Trademark Office during the preceding fiscal year which were supported by patent fee expenditures, trademark fee expenditures, and appropriations;"],[1,"(3) budget plans for significant programs, projects, and activities of the Office, including out-year funding estimates;"],[1,"(4) any proposed disposition of surplus fees by the Office; and"],[1,"(5) such other information as the committees consider necessary."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/35/42?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§42. Patent and Trademark Office funding","tname":"Patents","by":{"1":"35"}},{"t":"law","label":"Dodd-Frank Wall Street Reform and Consumer Protection Act, Pub. L. No. 111-203","url":"https://www.govinfo.gov/link/plaw/111/public/203","by":{"1":"4"}},{"t":"reg","label":"12 C.F.R. § 1041.7","url":"https://www.ecfr.gov/current/title-12/section-1041.7","by":{"1":"7"}},{"t":"reg","label":"12 C.F.R. § 1041.8","url":"https://www.ecfr.gov/current/title-12/section-1041.8","by":{"1":"7"}},{"t":"case","label":"Haaland v. Brackeen","cite":"143 S. Ct. 1609","y":2023,"id":"2022/21-376","sc":1,"sum":"In child custody proceedings governed by the Indian Child Welfare Act, the Court affirms the Fifth Circuit’s conclusion that ICWA is consistent with Congress’s Article I authority, rejects petitioners’ anticommandeering challenges under the Tenth Amendment, and finds the parties lack standing to litigate their other challenges to ICWA’s placement preferences.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"19"}},{"t":"case","label":"Herring v. United States","cite":"555 U.S. 135","y":2009,"id":"2008/07-513","sc":1,"sum":"The Court found that a criminal defendant's Fourth Amendment rights were not violated when he was unlawfully searched due to isolated negligence of police and not \"systematic error or reckless disregard of constitutional requirements.\"","sumSrc":"Oyez","by":{"2":"22"}},{"t":"case","label":"NLRB v. SW Gen., Inc.","cite":"580 U.S. 288","y":2017,"url":"https://supreme.justia.com/cases/federal/us/580/288/","sc":1,"by":{"2":"5"}},{"t":"case","label":"Salazar v. Ramah Navajo Chapter","cite":"567 U.S. 182","y":2012,"id":"2011/11-551","sc":1,"sum":"The Court held that, under the Indian Self-Determination and Education Assistance Act, the government is required to pay all of the contract support costs incurred by a tribal contractor if payment of those costs would exceed the statutory cap on the appropriations available to pay them.","sumSrc":"Oyez","by":{"2":"21"}},{"t":"const","label":"Article I, Section 7, Clause 1","clauses":[["origination","Origination Clause"]],"text":"All Bills for raising Revenue shall originate in the House of Representatives; but the Senate may propose or concur with Amendments as on other Bills.","by":{"2":"13"}},{"t":"usc","label":"15 U.S.C. § 9021","url":"https://www.law.cornell.edu/uscode/text/15/9021","subs":["(g)(1)(B)"],"by":{"2":"4"}},{"t":"usc","label":"15 U.S.C. § 9023","url":"https://www.law.cornell.edu/uscode/text/15/9023","subs":["(d)(3)"],"stext":{"head":"§9023. Emergency increase in unemployment compensation benefits","paras":[[0,"(a) Federal-State agreements"],[0,"Any State which desires to do so may enter into and participate in an agreement under this section with the Secretary of Labor (in this section referred to as the \"Secretary\"). Any State which is a party to an agreement under this section may, upon providing 30 days' written notice to the Secretary, terminate such agreement."],[0,"(b) Provisions of agreement"],[0,"(1) Federal Pandemic Unemployment Compensation"],[1,"Any agreement under this section shall provide that the State agency of the State will make payments of regular compensation to individuals in amounts and to the extent that they would be determined if the State law of the State were applied, with respect to any week for which the individual is (disregarding this section) otherwise entitled under the State law to receive regular compensation, as if such State law had been modified in a manner such that the amount of regular compensation (including dependents' allowances) payable for any week shall be equal to—"],[2,"(A) the amount determined under the State law (before the application of this paragraph), plus"],[2,"(B) an additional amount equal to the amount specified in paragraph (3) (in this section referred to as \"Federal Pandemic Unemployment Compensation\"), plus"],[2,"(C) an additional amount of $100 (in this section referred to as \"Mixed Earner Unemployment Compensation\") in any case in which the individual received at least $5,000 of self-employment income (as defined in section 1402(b) of title 26) in the most recent taxable year ending prior to the individual's application for regular compensation."],[0,"(2) Allowable methods of payment"],[1,"Any Federal Pandemic Unemployment Compensation or Mixed Earner Unemployment Compensation provided for in accordance with paragraph (1) shall be payable either—"],[2,"(A) as an amount which is paid at the same time and in the same manner as any regular compensation otherwise payable for the week involved; or"],[2,"(B) at the option of the State, by payments which are made separately from, but on the same weekly basis as, any regular compensation otherwise payable."],[0,"(3) Amount of Federal Pandemic Unemployment Compensation"],[0,"(A) 1 In general"],[2,"The amount specified in this paragraph is the following amount:"],[3,"(i) For weeks of unemployment beginning after the date on which an agreement is entered into under this section and ending on or before July 31, 2020, $600."],[3,"(ii) For weeks of unemployment beginning after December 26, 2020 (or, if later, the date on which such agreement is entered into), and ending on or before September 6, 2021, $300."],[0,"(4) Certain documentation required"],[1,"An agreement under this section shall include a requirement, similar to the requirement under section 9021(a)(3)(A)(iii) of this title, for the substantiation of self-employment income with respect to each applicant for Mixed Earner Unemployment Compensation under paragraph (1)(C)."],[0,"(c) Nonreduction rule"],[0,"(1) In general"],[1,"An agreement under this section shall not apply (or shall cease to apply) with respect to a State upon a determination by the Secretary that the method governing the computation of regular compensation under the State law of that State has been modified in a manner such that the number of weeks (the maximum benefit entitlement), or the average weekly benefit amount, of regular compensation which will be payable during the period of the agreement (determined disregarding any Federal Pandemic Unemployment Compensation or Mixed Earner Unemployment Compensation) will be less than the number of weeks, or the average weekly benefit amount, of the average weekly benefit amount of regular compensation which would otherwise have been payable during such period under the State law, as in effect on January 1, 2020."],[0,"(2) Maximum benefit entitlement"],[1,"In paragraph (1), the term \"maximum benefit entitlement\" means the amount of regular unemployment compensation payable to an individual with respect to the individual's benefit year."],[0,"(d) Payments to States"],[0,"(1) In general"],[0,"(A) Full reimbursement"],[2,"There shall be paid to each State which has entered into an agreement under this section an amount equal to 100 percent of—"],[3,"(i) the total amount of Federal Pandemic Unemployment Compensation and Mixed Earner Unemployment Compensation paid to individuals by the State pursuant to such agreement; and"],[3,"(ii) any additional administrative expenses incurred by the State by reason of such agreement (as determined by the Secretary)."],[0,"(B) Terms of payments"],[2,"Sums payable to any State by reason of such State's having an agreement under this section shall be payable, either in advance or by way of reimbursement (as determined by the Secretary), in such amounts as the Secretary estimates the State will be entitled to receive under this section for each calendar month, reduced or increased, as the case may be, by any amount by which the Secretary finds that his estimates for any prior calendar month were greater or less than the amounts which should have been paid to the State. Such estimates may be made on the basis of such statistical, sampling, or other method as may be agreed upon by the Secretary and the State agency of the State involved."],[0,"(2) Certifications"],[1,"The Secretary shall from time to time certify to the Secretary of the Treasury for payment to each State the sums payable to such State under this section."],[0,"(3) Appropriation"],[1,"There are appropriated from the general fund of the Treasury, without fiscal year limitation, such sums as may be necessary for purposes of this subsection."],[0,"(e) Applicability"],[0,"An agreement entered into under this section shall apply—"],[1,"(1) to weeks of unemployment beginning after the date on which such agreement is entered into and ending on or before July 31, 2020; and"],[1,"(2) to weeks of unemployment beginning after December 26, 2020 (or, if later, the date on which such agreement is entered into), and ending on or before September 6, 2021."],[0,"(f) Fraud and overpayments"],[0,"(1) In general"],[1,"If an individual knowingly has made, or caused to be made by another, a false statement or representation of a material fact, or knowingly has failed, or caused another to fail, to disclose a material fact, and as a result of such false statement or representation or of such nondisclosure such individual has received an amount of Federal Pandemic Unemployment Compensation or Mixed Earner Unemployment Compensation to which such individual was not entitled, such individual—"],[2,"(A) shall be ineligible for further Federal Pandemic Unemployment Compensation or Mixed Earner Unemployment Compensation in accordance with the provisions of the applicable State unemployment compensation law relating to fraud in connection with a claim for unemployment compensation; and"],[2,"(B) shall be subject to prosecution under section 1001 of title 18."],[0,"(2) Repayment"],[1,"In the case of individuals who have received amounts of Federal Pandemic Unemployment Compensation or Mixed Earner Unemployment Compensation to which they were not entitled, the State shall require such individuals to repay the amounts of such Federal Pandemic Unemployment Compensation or Mixed Earner Unemployment Compensation to the State agency, except that the State agency may waive such repayment if it determines that—"],[2,"(A) the payment of such Federal Pandemic Unemployment Compensation or Mixed Earner Unemployment Compensation was without fault on the part of any such individual; and"],[2,"(B) such repayment would be contrary to equity and good conscience."],[0,"(3) Recovery by State agency"],[0,"(A) In general"],[2,"The State agency shall recover the amount to be repaid, or any part thereof, by deductions from any Federal Pandemic Unemployment Compensation or Mixed Earner Unemployment Compensation payable to such individual or from any unemployment compensation payable to such individual under any State or Federal unemployment compensation law administered by the State agency or under any other State or Federal law administered by the State agency which provides for the payment of any assistance or allowance with respect to any week of unemployment, during the 3-year period after the date such individuals received the payment of the Federal Pandemic Unemployment Compensation or Mixed Earner Unemployment Compensation to which they were not entitled, in accordance with the same procedures as apply to the recovery of overpayments of regular unemployment benefits paid by the State."],[0,"(B) Opportunity for hearing"],[2,"No repayment shall be required, and no deduction shall be made, until a determination has been made, notice thereof and an opportunity for a fair hearing has been given to the individual, and the determination has become final."],[0,"(4) Review"],[1,"Any determination by a State agency under this section shall be subject to review in the same manner and to the same extent as determinations under the State unemployment compensation law, and only in that manner and to that extent."],[0,"(g) Application to other unemployment benefits"],[0,"Each agreement under this section shall include provisions to provide that—"],[1,"(1) the purposes of the preceding provisions of this section, as such provisions apply with respect to Federal Pandemic Unemployment Compensation, shall be applied with respect to unemployment benefits described in subsection (i)(2) to the same extent and in the same manner as if those benefits were regular compensation; and"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/9023?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§9023. Emergency increase in unemployment compensation benefits","tname":"Commerce and Trade","by":{"2":"4"}},{"t":"usc","label":"19 U.S.C. § 58b","url":"https://www.law.cornell.edu/uscode/text/19/58b","subs":["(e)"],"by":{"2":"17"}}]};